INSERT INTO lessons (id, chapter_id, title, description, content, vocabulary, examples, pronunciation, order_num, is_free, xp_reward, duration, createdAt) VALUES
('0ea6b0de-e1ec-57e3-b044-353e91909f84', '424fcebe-5852-525f-8406-2af3748d0c59', 'الأسماء والجنس - Los Sustantivos', 'المذكر والمؤنث والمفرد والجمع', 'كل اسم إسباني مذكر أو مؤنث، ويُحفظ دائماً مع أداته: el libro (الكتاب)، la mesa (الطاولة). القاعدة العامة: المنتهي بـ o مذكر والمنتهي بـ a مؤنث، مع استثناءات مشهورة يجب حفظها.', '[{"es":"el libro","ar":"الكتاب"},{"es":"la mesa","ar":"الطاولة"},{"es":"la mano","ar":"اليد"},{"es":"el día","ar":"اليوم"},{"es":"la ciudad","ar":"المدينة"}]'::jsonb, '[{"es":"El libro nuevo es de Ahmed.","ar":"الكتاب الجديد لأحمد."},{"es":"El día está soleado.","ar":"اليوم مشمس."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('0a1e855d-291d-5771-9404-41b08c7e0487', '424fcebe-5852-525f-8406-2af3748d0c59', 'تكوين الجمع - El Plural', 'تحويل المفرد إلى جمع', 'نضيف s بعد حرف العلة (libro → libros)، وes بعد الحرف الساكن (ciudad → ciudades)، والاسم المنتهي بـ z يتحول إلى ces عند الجمع (lápiz → lápices).', '[{"es":"los libros","ar":"الكتب"},{"es":"las ciudades","ar":"المدن"},{"es":"los lápices","ar":"أقلام الرصاص"},{"es":"las mujeres","ar":"النساء"}]'::jsonb, '[{"es":"Una ciudad pequeña, dos ciudades grandes.","ar":"مدينة صغيرة، مدينتان كبيرتان."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('3aacaf2a-5ca8-55c3-932d-87f8c85b656b', '424fcebe-5852-525f-8406-2af3748d0c59', 'صفات الملكية - Los Posesivos', 'mi، tu، su، nuestros...', 'صفات الملكية تطابق الموصوف لا المالك: mi libro (كتابي)، mis libros (كتبي)، nuestra casa (بيتنا). وكلمة su تعني ملكه/ملكها/ملككم حسب السياق.', '[{"es":"mi casa","ar":"بيتي"},{"es":"tu coche","ar":"سيارتك"},{"es":"su familia","ar":"عائلته"},{"es":"nuestros amigos","ar":"أصدقاؤنا"}]'::jsonb, '[{"es":"Mi casa es tu casa.","ar":"بيتي بيتك."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('870a54bc-7a7c-5717-bc7b-df85e7ccb231', '424fcebe-5852-525f-8406-2af3748d0c59', 'أسماء الإشارة - Los Demostrativos', 'este، ese، aquel', 'este/esta للقريب من المتحدث، وese/esa للمتوسط البعد، وaquel/aquella للبعيد عن الطرفين: este libro (في يدي)، aquel libro (هناك بعيداً).', '[{"es":"este libro","ar":"هذا الكتاب (قريب)"},{"es":"esa casa","ar":"تلك الدار (متوسطة البعد)"},{"es":"aquel árbol","ar":"تلك الشجرة (بعيدة)"},{"es":"estos días","ar":"هذه الأيام"}]'::jsonb, '[{"es":"Esta mesa es nueva, aquella es vieja.","ar":"هذه الطاولة جديدة وتلك البعيدة قديمة."}]'::jsonb, '[]'::jsonb, 4, TRUE, 30, 15, now()),
('58992978-2134-5c83-bf75-685605cd6e09', '424fcebe-5852-525f-8406-2af3748d0c59', 'الأعداد الترتيبية - Los Ordinales', 'primero، segundo، tercero...', 'الأعداد الترتيبية: primero، segundo، tercero، cuarto، quinto... وتوضع قبل الاسم، ويفقد primero وtercero حرف o الأخير مع المذكر: el primer día، el tercer piso.', '[{"es":"primero","ar":"الأول"},{"es":"segundo","ar":"الثاني"},{"es":"tercero","ar":"الثالث"},{"es":"quinto","ar":"الخامس"}]'::jsonb, '[{"es":"Vivo en el tercer piso.","ar":"أسكن في الطابق الثالث."}]'::jsonb, '[]'::jsonb, 5, TRUE, 30, 15, now()),
('85142f00-96c1-5201-bccd-64f5f91c8b21', '424fcebe-5852-525f-8406-2af3748d0c59', 'زمن المضارع - El Presente', 'تصريف الأفعال في المضارع', 'المضارع يعبّر عن الحاضر والعادة: hablo (أتحدث)، estudiamos (ندرس). نهايات مجموعة -ar: o، as، a، amos، áis، an، ونحذف الضمير لأن النهاية تدل على الفاعل.', '[{"es":"hablo","ar":"أتحدث"},{"es":"estudiamos","ar":"ندرس"},{"es":"trabaja","ar":"يعمل"},{"es":"vives","ar":"تسكن"}]'::jsonb, '[{"es":"Estudiamos español los lunes.","ar":"ندرس الإسبانية أيام الاثنين."}]'::jsonb, '[]'::jsonb, 6, TRUE, 30, 15, now()),
('860cd1f7-680c-5a40-9ddf-66fe2f10e4ef', 'b6c98ff4-ff76-507b-94ec-6b1d2b71b547', 'الأفعال المنتظمة - Verbos Regulares', 'مجموعات ar و er و ir', 'تنقسم الأفعال المنتظمة إلى ثلاث مجموعات تنتهي بـ -ar و-er و-ir، ولكل منها نهايات ثابتة: comer → como، comes، come؛ vivir → vivo، vives، vive.', '[{"es":"comer","ar":"يأكل"},{"es":"vivir","ar":"يسكن"},{"es":"bebo","ar":"أشرب"},{"es":"aprendes","ar":"تتعلم"}]'::jsonb, '[{"es":"Como a las dos y vivo cerca.","ar":"آكل في الثانية وأسكن قريباً."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('077507be-09bd-5d5d-aaa5-23362045c54c', 'b6c98ff4-ff76-507b-94ec-6b1d2b71b547', 'الأفعال الشاذة في المضارع - Verbos Irregulares', 'أهم الأفعال متغيرة الجذر', 'أشهر الأفعال الشاذة في المضارع: tener → tengo، hacer → hago، decir → digo، ver → veo، oír → oigo. تُحفظ كما هي لشيوعها في الكلام اليومي.', '[{"es":"tengo","ar":"عندي"},{"es":"hago","ar":"أفعل"},{"es":"digo","ar":"أقول"},{"es":"veo","ar":"أرى"}]'::jsonb, '[{"es":"Hago mi tarea todos los días.","ar":"أنجز واجبي كل يوم."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('80782318-150c-5c24-bde7-ccbf0163746e', 'b6c98ff4-ff76-507b-94ec-6b1d2b71b547', 'النفي - La Negación', 'no، nunca، nada، nadie', 'نضع no قبل الفعل: No quiero. وعند النفي الشامل نستخدم nunca (أبداً) وnada (لا شيء) وnadie (لا أحد)، ولا نجمع أكثر من نفي في الجملة: No veo nada.', '[{"es":"No quiero","ar":"لا أريد"},{"es":"nunca","ar":"أبداً"},{"es":"nada","ar":"لا شيء"},{"es":"nadie","ar":"لا أحد"}]'::jsonb, '[{"es":"No hay nada en la nevera.","ar":"لا يوجد شيء في الثلاجة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('16dd5d4e-5d49-5370-8d57-aaf22239848e', 'b6c98ff4-ff76-507b-94ec-6b1d2b71b547', 'تكوين الأسئلة - Las Preguntas', 'أدوات الاستفهام وترتيب الجملة', 'نفتتح السؤال بعلامة ¿ ونستخدم: ¿Qué? ماذا، ¿Dónde? أين، ¿Cuándo? متى، ¿Quién? من، ¿Cómo? كيف، ¿Cuánto? كم. ويمكن السؤال بالنبر وحده: ¿Hablas español?', '[{"es":"¿Qué?","ar":"ماذا؟"},{"es":"¿Dónde?","ar":"أين؟"},{"es":"¿Cuándo?","ar":"متى؟"},{"es":"¿Cuánto cuesta?","ar":"كم يكلف؟"}]'::jsonb, '[{"es":"¿Dónde está la estación?","ar":"أين المحطة؟"}]'::jsonb, '[]'::jsonb, 4, TRUE, 30, 15, now()),
('d4e22a54-2a4d-5542-9929-e1266acb2dca', 'b6c98ff4-ff76-507b-94ec-6b1d2b71b547', 'التعبير عن الوجود - Hay', 'يوجد / توجد', 'hay ثابتة للمفرد والجمع ولا تتغير: Hay un problema، Hay dos problemas. ولا نضع بعدها أداة تعريف: Hay libros (توجد كتب). وفي الماضي: había.', '[{"es":"Hay","ar":"يوجد"},{"es":"¿Hay...?","ar":"هل يوجد...؟"},{"es":"No hay","ar":"لا يوجد"},{"es":"Había","ar":"كان يوجد"}]'::jsonb, '[{"es":"¿Hay un banco por aquí?","ar":"هل يوجد بنك في الجوار؟"}]'::jsonb, '[]'::jsonb, 5, TRUE, 30, 15, now()),
('988f4dbc-bdd4-56c2-acf4-109b41f807dd', 'b6c98ff4-ff76-507b-94ec-6b1d2b71b547', 'الاختصاران Al و Del - Las Contracciones', 'a+el=al و de+el=del', 'الاختصاران الوحيدان في الإسبانية: a + el = al (Voy al médico)، وde + el = del (el coche del vecino). ولا اختصار مع la ولا los ولا las.', '[{"es":"Voy al mercado","ar":"أذهب إلى السوق"},{"es":"el libro del profesor","ar":"كتاب الأستاذ"},{"es":"al lado del parque","ar":"بجانب الحديقة"},{"es":"delante del cine","ar":"أمام السينما"}]'::jsonb, '[{"es":"Voy al banco del centro.","ar":"أذهب إلى بنك المركز."}]'::jsonb, '[]'::jsonb, 6, TRUE, 30, 15, now()),
('a853fb85-fc8d-5068-8bb1-9b4be0993f86', 'b6c98ff4-ff76-507b-94ec-6b1d2b71b547', 'حروف الجر - Las Preposiciones', 'en، de، a، con، sin، para', 'أهم حروف الجر: en (في)، de (من/الخاصية)، a (إلى)، con (مع)، sin (بدون)، sobre (على/حول). مثال: el libro de Ahmed، café con leche sin azúcar.', '[{"es":"en casa","ar":"في البيت"},{"es":"de Madrid","ar":"من مدريد"},{"es":"con amigos","ar":"مع أصدقاء"},{"es":"sin azúcar","ar":"بدون سكر"}]'::jsonb, '[{"es":"Un café con leche, sin azúcar, por favor.","ar":"قهوة بالحليب، بدون سكر، من فضلك."}]'::jsonb, '[]'::jsonb, 7, TRUE, 30, 15, now()),
('d69efb28-2323-59b3-9f6c-b75759b249ea', 'b6c98ff4-ff76-507b-94ec-6b1d2b71b547', 'ظروف التكرار - Adverbios de Frecuencia', 'siempre، a veces، nunca...', 'ظروف التكرار توضع قبل الفعل المصرّف: Siempre estudio. والترتيب من الأكثر للأقل: siempre (دائماً)، a menudo (غالباً)، a veces (أحياناً)، casi nunca (نادراً)، nunca (أبداً).', '[{"es":"siempre","ar":"دائماً"},{"es":"a menudo","ar":"غالباً"},{"es":"a veces","ar":"أحياناً"},{"es":"nunca","ar":"أبداً"}]'::jsonb, '[{"es":"A veces cocino, pero nunca lavo los platos.","ar":"أحياناً أطبخ، لكني لا أغسل الأواني أبداً."}]'::jsonb, '[]'::jsonb, 8, TRUE, 30, 15, now()),
('6778249e-94bf-59af-847d-623e11dc6c4a', '3d8b5aad-a84b-5065-a2de-9c6b32a68ed4', 'المضارع المستمر - El Presente Continuo', 'estar + gerundio', 'نكوّنه بـ estar + اسم الفاعل: -ando لمجموعة -ar و-iendo لغيرها: Estoy estudiando (أنا أدرس الآن)، Está lloviendo (إنها تمطر الآن).', '[{"es":"Estoy estudiando","ar":"أنا أدرس الآن"},{"es":"está lloviendo","ar":"إنها تمطر"},{"es":"están comiendo","ar":"هم يأكلون الآن"},{"es":"estás escribiendo","ar":"أنت تكتب الآن"}]'::jsonb, '[{"es":"No puedo salir, está lloviendo.","ar":"لا أستطيع الخروج، إنها تمطر."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('d32551e4-6fca-542b-93d1-f2d3f975685e', '3d8b5aad-a84b-5065-a2de-9c6b32a68ed4', 'الماضي القريب - El Pretérito Perfecto', 'he + participio', 'نكوّنه بـ haber + التصريف الثالث: He hablado، Has comido، Hemos visto. ويستعمل مع فترة زمنية لم تنته بعد: hoy، esta semana، este año.', '[{"es":"He comido","ar":"أكلتُ"},{"es":"Has visto","ar":"رأيتَ"},{"es":"Hemos terminado","ar":"انتهينا"},{"es":"Este año he viajado","ar":"هذه السنة سافرتُ"}]'::jsonb, '[{"es":"Hoy he estudiado dos horas.","ar":"درستُ اليوم ساعتين."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('600e647a-b4f6-57c9-875c-7d8f41b1fabf', '3d8b5aad-a84b-5065-a2de-9c6b32a68ed4', 'المستقبل القريب - El Futuro Próximo', 'ir a + مصدر', 'نكوّنه بـ فعل ir في المضارع + a + المصدر: Voy a estudiar (سأدرس)، Vamos a viajar (سنرحل). يعبّر عن خطط ونية قريبة مؤكدة.', '[{"es":"Voy a estudiar","ar":"سأدرس"},{"es":"Vas a trabajar","ar":"سوف تعمل"},{"es":"Vamos a viajar","ar":"سنذهب في رحلة"},{"es":"Va a llover","ar":"ستمطر"}]'::jsonb, '[{"es":"Esta tarde voy a visitar a mi abuela.","ar":"بعد الظهر سأزور جدتي."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('3490a8e3-a85a-587d-9c28-26eaadb9cdf7', '3d8b5aad-a84b-5065-a2de-9c6b32a68ed4', 'صيغة الأمر - El Imperativo', 'الأوامر والطلبات', 'للمخاطب المفرد (tú): صيغة المضارع للإثبات ¡Habla! (تحدثْ)، ولا + صيغة subjuntivo للنهر: ¡No hables! ومن الشواذ: ¡Ven! (تعالْ)، ¡Hazlo! (افعله).', '[{"es":"¡Habla!","ar":"تحدثْ!"},{"es":"¡Escucha!","ar":"استمعْ!"},{"es":"¡Ven aquí!","ar":"تعال هنا!"},{"es":"¡No hables!","ar":"لا تتحدث!"}]'::jsonb, '[{"es":"¡Ven aquí y escucha bien!","ar":"تعال هنا واستمع جيداً!"}]'::jsonb, '[]'::jsonb, 4, TRUE, 30, 15, now()),
('573fb1e3-4ea9-526c-a97b-b71921b9e6ba', '464f4560-711d-5082-8b28-1a46809e8586', 'أفعال القدرة والوجوب - Verbos Modales', 'poder، querer، deber، tener que', 'Puedo hablar (أستطيع التحدث)، Quiero aprender (أريد التعلم)، Debo/Tengo que trabajar (يجب أن أعمل). يتبع هذه الأفعالَ المصدرُ مباشرة دون حرف جر.', '[{"es":"puedo","ar":"أستطيع"},{"es":"quiero","ar":"أريد"},{"es":"debo","ar":"يجب عليّ"},{"es":"tengo que","ar":"يجب أن"}]'::jsonb, '[{"es":"Tengo que estudiar, pero quiero dormir.","ar":"يجب أن أدرس، لكني أريد النوم."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('584e0abc-0738-5508-9166-2a2e09fa7f1b', '464f4560-711d-5082-8b28-1a46809e8586', 'فروق Ser و Estar - Ser y Estar', 'متى نستخدم كل واحد', 'ser للهوية والصفات الدائمة والمهنة، وestar للمكان والحالة المؤقتة والنتيجة: Es aburrido (ممل بطبعه) ≠ Está aburrido (يشعر بملل)، La comida está buena (لذيذة الآن).', '[{"es":"Soy médico","ar":"أنا طبيب (مهنة)"},{"es":"Estoy cansado","ar":"أنا متعب (حالة)"},{"es":"El libro es nuevo","ar":"الكتاب جديد (صفة دائمة)"},{"es":"Está en casa","ar":"هو في البيت (مكان)"}]'::jsonb, '[{"es":"La sopa está muy rica hoy.","ar":"الشوربة لذيذة جداً اليوم."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('19f51bc3-9b4b-5384-b04f-cc38b047fc82', '464f4560-711d-5082-8b28-1a46809e8586', 'الفرق بين Por و Para - Por y Para', 'حرفان يظنهما المبتدئ واحداً', 'por للسبب والتبادل والمدة والمكان المرور: gracias por tu ayuda، por la mañana. وpara للغاية والمستقبل والمقابل: para ti، para mañana، estudio para aprender.', '[{"es":"gracias por...","ar":"شكراً على..."},{"es":"por la mañana","ar":"في الصباح"},{"es":"para ti","ar":"لأجلك"},{"es":"para mañana","ar":"لغدٍ"}]'::jsonb, '[{"es":"Este regalo es para ti.","ar":"هذه الهدية لك."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('a76028ec-130e-5ccb-ac15-a18d54268d00', '464f4560-711d-5082-8b28-1a46809e8586', 'Saber و Conocer - Saber y Conocer', 'معرفة المعلومة أم معرفة الشخص', 'saber لمعلومة أو مهارة: Sé la respuesta (أعرف الجواب)، Sé nadar (أتقن السباحة). وconocer لشخص أو مكان عايشته: Conozco Madrid (أعرف مدريد بالخبرة).', '[{"es":"No sé","ar":"لا أعرف (معلومة)"},{"es":"Sé nadar","ar":"أتقن السباحة"},{"es":"Conozco a tu hermano","ar":"أعرف أخاك"},{"es":"¿Conoces España?","ar":"هل زرت/تعرف إسبانيا؟"}]'::jsonb, '[{"es":"Sé hablar español y conozco Granada.","ar":"أتقن الإسبانية وأعرف غرناطة."}]'::jsonb, '[]'::jsonb, 4, TRUE, 30, 15, now()),
('130e14e8-6ae5-5b2a-89d6-114c270f4e3f', '464f4560-711d-5082-8b28-1a46809e8586', 'ضمائر المفعول به - Pronombres de Objeto', 'me، te، lo، la، los، las', 'ضمائر المفعول تحل محل المفعول وتسبق الفعل المصرّف: ¿El libro? Lo tengo (أمتلكه). وتلحق المصدر مباشرة: Quiero verlo (أريد رؤيته).', '[{"es":"Lo veo","ar":"أراه"},{"es":"La conozco","ar":"أعرفها"},{"es":"Me ayudas","ar":"تساعدني"},{"es":"Escúchame","ar":"استمع إليّ"}]'::jsonb, '[{"es":"¿Has visto a María? Sí, la he visto.","ar":"هل رأيت ماريا؟ نعم، رأيتها."}]'::jsonb, '[]'::jsonb, 5, TRUE, 30, 15, now()),
('3f5e3f64-dc1c-5630-acf7-540791fb2728', '464f4560-711d-5082-8b28-1a46809e8586', 'المقارنة والتفضيل - Comparativos y Superlativos', 'más...que والمفضّل', 'المقارنة: más/menos + صفة + que: Ahmed es más alto que Karim. والمساواة: tan...como. والتفضيل: el/la más + صفة، ومن الشواذ: mejor (أفضل) وpeor (أسوأ).', '[{"es":"más alto que","ar":"أطول من"},{"es":"tan rápido como","ar":"سريع مثله"},{"es":"el más fácil","ar":"الأسهل"},{"es":"mejor","ar":"أفضل"}]'::jsonb, '[{"es":"Esta película es más interesante que aquella.","ar":"هذا الفيلم أكثر تشويقاً من ذاك."}]'::jsonb, '[]'::jsonb, 6, TRUE, 30, 15, now()),
('6b925589-2a49-55f9-8c79-f273dae48da4', '67061d6b-ad66-53a2-9e24-cec6fad607fc', 'الماضي الأسبق - El Pluscuamperfecto', 'había + participio', 'حدث اكتمل قبل حدث ماضٍ آخر: Cuando llegué, la película ya había empezado (عندما وصلت، كان الفيلم قد بدأ). تصريف haber في imperfecto: había، habías، había...', '[{"es":"había comido","ar":"كنت قد أكلت"},{"es":"había llegado","ar":"كان قد وصل"},{"es":"habíamos visto","ar":"كنا قد رأينا"},{"es":"ya había salido","ar":"كان قد خرج"}]'::jsonb, '[{"es":"Cuando llegué a casa, mi familia ya había cenado.","ar":"عندما وصلت إلى البيت، كانت عائلتي قد تعشت."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('f793a8af-12dc-5953-ad6f-11e8131589fe', '67061d6b-ad66-53a2-9e24-cec6fad607fc', 'المستقبل التام - El Futuro Perfecto', 'habré + participio', 'ما سيكون قد اكتمل قبل لحظة مستقبلية: Para las ocho, habré terminado (بحلول الثامنة سأكون قد انتهيت).', '[{"es":"habré terminado","ar":"سأكون قد انتهيت"},{"es":"habrás comido","ar":"ستكون قد أكلت"},{"es":"habrá llegado","ar":"سيكون قد وصل"},{"es":"habremos visto","ar":"سنكون قد رأينا"}]'::jsonb, '[{"es":"Para el lunes ya habré terminado el trabajo.","ar":"بحلول الاثنين سأكون قد أنهيت العمل."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('0d39b537-955e-5e78-b758-38706b47c6e7', '67061d6b-ad66-53a2-9e24-cec6fad607fc', 'الشرط المركب - El Condicional Compuesto', 'habría + participio', 'نتيجة لم تتحقق في الماضي: Si hubiera estudiado, habría aprobado (لو كنت درست لكنت نجحت). يتركب من habría + التصريف الثالث.', '[{"es":"habría ido","ar":"كنت سأذهب"},{"es":"habría dicho","ar":"كنت سأقول"},{"es":"habríamos ganado","ar":"كنا سنفوز"},{"es":"habría comido","ar":"كنت سآكل"}]'::jsonb, '[{"es":"Si hubiera tenido tiempo, habría viajado.","ar":"لو كان عندي وقت لكنت سافرت."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('eca2731a-afc8-541c-a45b-02637e1f870d', '67061d6b-ad66-53a2-9e24-cec6fad607fc', 'الماضي التابع - El Imperfecto de Subjuntivo', 'tuviera / tuviese', 'يتكون من همزة الماضي البسيط: tuviera/tuviese، hablara/hablase. للأمنيات البعيدة والشرط غير الواقعي: Si tuviera dinero...، Ojalá pudiera (ليتني أستطيع).', '[{"es":"si tuviera","ar":"لو كان عندي"},{"es":"pudiera","ar":"لو استطعت"},{"es":"quisiera","ar":"أودّ (بلطف)"},{"es":"ojalá pudiera","ar":"ليتني أستطيع"}]'::jsonb, '[{"es":"Si pudiera, viajaría por el mundo.","ar":"لو استطعت، لسافرت حول العالم."}]'::jsonb, '[]'::jsonb, 4, TRUE, 30, 15, now()),
('13af96b9-44bb-58c4-9d4d-97d6661e7858', '67061d6b-ad66-53a2-9e24-cec6fad607fc', 'الجمل الشرطية - Oraciones Condicionales', 'الأنواع الثلاثة للشرط', 'النوع 1 قابل للتحقق: Si estudio, aprobaré. النوع 2 افتراضي: Si estudiara, aprobaría. النوع 3 ماضٍ مستحيل: Si hubiera estudiado, habría aprobado.', '[{"es":"Si estudio, aprobaré","ar":"إن أدرس سأنجح"},{"es":"Si tuviera tiempo, iría","ar":"لو كان عندي وقت لذهبت"},{"es":"Si hubiera sabido...","ar":"لو كنت علمت..."},{"es":"aprobar","ar":"ينجح"}]'::jsonb, '[{"es":"Si tengo tiempo mañana, te llamaré.","ar":"إن كان عندي وقت غداً، سأتصل بك."}]'::jsonb, '[]'::jsonb, 5, TRUE, 30, 15, now()),
('0a1420c8-bebe-5559-9802-6524d7c109a5', '67061d6b-ad66-53a2-9e24-cec6fad607fc', 'الكلام غير المباشر - El Estilo Indirecto', 'نقل كلام الآخرين', 'قال: «Estoy cansado» → Dijo que estaba cansado. الأزمنة تتراجع خطوة إلى الماضي، وسؤال نعم/لا يُنقل بـ si: Me preguntó si estaba cansado.', '[{"es":"dijo que","ar":"قال إن"},{"es":"me preguntó si","ar":"سألني هل"},{"es":"me pidió que","ar":"طلب مني أن"},{"es":"contestó que","ar":"أجاب بأن"}]'::jsonb, '[{"es":"Me preguntó si quería café.","ar":"سألني هل أريد قهوة."}]'::jsonb, '[]'::jsonb, 6, TRUE, 30, 15, now()),
('07cb5415-c020-5500-b8df-98459351ed62', '67061d6b-ad66-53a2-9e24-cec6fad607fc', 'الجمل الموصولة - Las Oraciones Relativas', 'que، quien، donde، cuyo', 'que للأشياء والأشخاص: el libro que leo. وdonde للمكان: la ciudad donde vivo. وquien للأشخاص فقط، وcuyo/cuya للملكية وتطابق ما بعدها: el chico cuya madre es médico.', '[{"es":"el libro que leo","ar":"الكتاب الذي أقرؤه"},{"es":"la ciudad donde nací","ar":"المدينة التي وُلدت فيها"},{"es":"la chica que habla","ar":"الفتاة التي تتحدث"},{"es":"el amigo con quien salgo","ar":"الصديق الذي أخرج معه"}]'::jsonb, '[{"es":"Ésta es la casa donde crecí.","ar":"هذا هو البيت الذي كبرت فيه."}]'::jsonb, '[]'::jsonb, 7, TRUE, 30, 15, now()),
('5c0b7dbd-cf28-5dfa-9d64-74a44c9f7edd', '67321c80-efc0-52a6-aa9f-2eb9f72e73f4', 'المبني للمجهول - La Voz Pasiva', 'ser + participio', 'المبني للمجهول: ser + التصريف الثالث + por: El Quijote fue escrito por Cervantes. وفي الكلام اليومي يُفضَّل المجهول بـ se: Se habla español، Se venden casas.', '[{"es":"fue escrito","ar":"كُتب"},{"es":"es hecho","ar":"يُصنع"},{"es":"fueron construidas","ar":"بُنيت"},{"es":"Se habla español","ar":"تُتحدث الإسبانية"}]'::jsonb, '[{"es":"La catedral fue construida en el siglo XVI.","ar":"بُنيت الكاتدرائية في القرن السادس عشر."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('f47810c5-fd5e-5fb9-8d4b-79f426b9c490', '67321c80-efc0-52a6-aa9f-2eb9f72e73f4', 'التراكيب الفعلية - Las Perífrasis Verbales', 'تركيبات تغيّر معنى الفعل', 'أشهرها: volver a + مصدر (التكرار): volví a llamarle، acabar de + مصدر (التوّ): acabo de llegar، llevar + gerundio (الاستمرار): llevo dos años estudiando.', '[{"es":"volver a llamar","ar":"يعاود الاتصال"},{"es":"acabar de llegar","ar":"يصل للتوّ"},{"es":"llevar + gerundio","ar":"يستمر منذ"},{"es":"seguir + gerundio","ar":"يواصل"}]'::jsonb, '[{"es":"Acabo de llegar y ya quiero volver.","ar":"وصلتُ للتو وأريد العودة بالفعل."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('fd161c35-e589-534c-aa7a-c28d26c2da93', '67321c80-efc0-52a6-aa9f-2eb9f72e73f4', 'المطابقة النحوية - La Concordancia', 'توافق الاسم والصفة والفعل', 'الصفة تطابق الاسم جنساً وعدداً: las flores rojas. والفعل يطابق فاعله: los niños juegan. وانتبه: كلمة la gente مفردة نحوياً: la gente es amable.', '[{"es":"las flores rojas","ar":"الزهور الحمراء"},{"es":"los niños juegan","ar":"الأطفال يلعبون"},{"es":"la gente es amable","ar":"الناس لطيفون"},{"es":"las casas blancas","ar":"البيوت البيضاء"}]'::jsonb, '[{"es":"Las casas viejas son baratas.","ar":"البيوت القديمة رخيصة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('2f7eba50-f23d-5ef6-94c2-d03e2af05d5e', '67321c80-efc0-52a6-aa9f-2eb9f72e73f4', 'النبر والترقيم - Acentos y Puntuación', 'علامات النبر والكتابة الصحيحة', 'علامة النبر تميّز المعنى: sí (نعم) ≠ si (إذا)، él (هو) ≠ el (الـ). والجملة الاستفهامية تبدأ بـ ¿ وتنتهي بعلامة الاستفهام، والتعجبية تبدأ بـ ¡.', '[{"es":"sí","ar":"نعم"},{"es":"si","ar":"إذا"},{"es":"él","ar":"هو"},{"es":"¡cuidado!","ar":"انتبه!"}]'::jsonb, '[{"es":"¡Sí, quiero ir!","ar":"نعم، أريد الذهاب!"}]'::jsonb, '[]'::jsonb, 4, TRUE, 30, 15, now()),
('5b70d643-1a47-50ff-9b94-3bb9544be93d', '67321c80-efc0-52a6-aa9f-2eb9f72e73f4', 'الأخطاء الشائعة - Errores Comunes', 'احذر هذه الأخطاء', 'أشهر أخطاء المتعلمين العرب: «Soy de acuerdo» والصحيح Estoy de acuerdo، و«Me gusto» والصحيح Me gusta، نقول Tengo 20 años لا Soy 20، وla gente es لا la gente son.', '[{"es":"Estoy de acuerdo","ar":"أنا موافق"},{"es":"Me gusta","ar":"يعجبني"},{"es":"Tengo 20 años","ar":"عمري 20 سنة"},{"es":"La gente es amable","ar":"الناس لطيفون"}]'::jsonb, '[{"es":"Estoy de acuerdo contigo.","ar":"أنا موافق معك."}]'::jsonb, '[]'::jsonb, 5, TRUE, 30, 15, now()),
('9338211f-33ca-546a-b3a9-d5019a929714', 'fbef5669-3da1-5023-a6d5-6c26b4bed105', 'الكتابة والتعبير - La Escritura', 'اكتب رسالة ووصفاً صحيحين', 'قوالب الرسالة: Estimado/a... للفتح وSaludos cordiales للختام. واربط أفكارك بأدوات الترتيب: en primer lugar (أولاً)، después (ثم)، finalmente (أخيراً).', '[{"es":"Estimado","ar":"عزيزي (افتتاح رسالة)"},{"es":"Saludos cordiales","ar":"تحياتي (ختام)"},{"es":"en primer lugar","ar":"أولاً"},{"es":"finalmente","ar":"أخيراً"}]'::jsonb, '[{"es":"Estimado Sr. García: Le escribo para... / Saludos cordiales.","ar":"عزيزي السيد غارسيا: أكتب إليك لكي... / تحياتي."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('b7fa2b2f-6bd7-5175-8932-a8a413476abc', 'fbef5669-3da1-5023-a6d5-6c26b4bed105', 'فهم النصوص - Comprensión Lectora', 'استراتيجيات القراءة', 'اقرأ العنوان أولاً، وابحث عن la idea principal (الفكرة الرئيسة)، وخمّن معنى الكلمات الجديدة من السياق قبل الرجوع إلى القاموس.', '[{"es":"el texto","ar":"النص"},{"es":"la idea principal","ar":"الفكرة الرئيسة"},{"es":"el título","ar":"العنوان"},{"es":"el párrafo","ar":"الفقرة"}]'::jsonb, '[{"es":"Lee el título y el primer párrafo antes de seguir.","ar":"اقرأ العنوان والفقرة الأولى قبل المتابعة."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('c780ae98-c8a7-5916-bf66-758a3269489c', 'fbef5669-3da1-5023-a6d5-6c26b4bed105', 'فهم المسموع - Comprensión Auditiva', 'كيف تُنمّي أذنك الإسبانية', 'اطلب الإعادة والتبطيء: ¿Puedes repetir?، Más despacio, por favor. التقط الأرقام والأسماء أولاً فهي مفاتيح المعنى، وكرر الاستماع قصيراً ومكثفاً.', '[{"es":"¿Puedes repetir?","ar":"هل يمكنك الإعادة؟"},{"es":"más despacio","ar":"أبطأ قليلاً"},{"es":"otra vez","ar":"مرة أخرى"},{"es":"el sonido","ar":"الصوت"}]'::jsonb, '[{"es":"¿Puedes repetir más despacio, por favor?","ar":"هل يمكنك الإعادة ببطء أكبر، من فضلك؟"}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('9cdb0dc6-9c6d-52c7-a279-8579d70839a1', 'fbef5669-3da1-5023-a6d5-6c26b4bed105', 'النطق والمحادثة - Pronunciación y Conversación', 'تحدث بثقة ووضوح', 'قواعد ذهبية: الـ j تُنطق خاءً (trabajo)، والـ h صامتة (hola)، والـ rr مكررة قوية (perro). وحافظ على تيار الحوار بردود قصيرة: ¿y tú?، ¿de verdad?', '[{"es":"el acento","ar":"النبر/اللهجة"},{"es":"la pronunciación","ar":"النطق"},{"es":"¿de verdad?","ar":"حقاً؟"},{"es":"¿y tú?","ar":"وأنت؟"}]'::jsonb, '[{"es":"Habla despacio, por favor.","ar":"تحدث ببطء، من فضلك."}]'::jsonb, '[]'::jsonb, 4, TRUE, 30, 15, now()) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, chapter_id, title, description, content, vocabulary, examples, pronunciation, order_num, is_free, xp_reward, duration, createdAt) VALUES
('b60dd0e8-3f9a-5af6-a658-959b74238501', '7e0b77fa-78ac-560f-9094-0d35fcf9b6ae', 'الملابس - La Ropa', 'مفردات اللبس والالتزام بالطقس', 'مفردات الملابس الأساسية، ونستخدم الفعل llevar (يلبس) لوصف ما نرتديه: Llevo una camisa blanca (ألبس قميصاً أبيض).', '[{"es":"la camisa","ar":"القميص"},{"es":"los pantalones","ar":"البنطال"},{"es":"el vestido","ar":"الفستان"},{"es":"los zapatos","ar":"الحذاء"},{"es":"la chaqueta","ar":"الجاكيت"}]'::jsonb, '[{"es":"Me pongo la chaqueta porque hace frío.","ar":"ألبس الجاكيت لأن الجو بارد."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('1a23dd5a-5cf4-57c5-bc91-1797be311b51', '7e0b77fa-78ac-560f-9094-0d35fcf9b6ae', 'جسم الإنسان - El Cuerpo Humano', 'أجزاء الجسم والتعبير عن الألم', 'أجزاء الجسم، وللتعبير عن الألم نستخدم doler مع الضمير: Me duele la cabeza (رأسي يؤلمني)، Me duelen los pies (قدماي تؤلمني).', '[{"es":"la cabeza","ar":"الرأس"},{"es":"la mano","ar":"اليد"},{"es":"el pie","ar":"القدم"},{"es":"los ojos","ar":"العيون"},{"es":"el estómago","ar":"المعدة"}]'::jsonb, '[{"es":"Me duele la cabeza y los ojos.","ar":"رأسي وعيناي يؤلمني."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('28361121-15d8-56cc-bee2-6a4a4c81731b', '38d16ca0-8cbb-55bb-a392-fdc249472a82', 'الفواكه والخضار - Frutas y Verduras', 'أسماء أشهر الفواكه والخضار', 'مفردات الفواكه والخضار أساسية للتسوق والطبخ. معظم أسمائها تأتي مع أداتها: la manzana، el tomate.', '[{"es":"la manzana","ar":"التفاحة"},{"es":"el tomate","ar":"البندورة"},{"es":"la naranja","ar":"البرتقالة"},{"es":"la zanahoria","ar":"الجزر"}]'::jsonb, '[{"es":"Como una manzana todos los días.","ar":"آكل تفاحة كل يوم."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('b63c6c5b-ac14-5953-ae22-fc48ad949d0f', '38d16ca0-8cbb-55bb-a392-fdc249472a82', 'وجبات اليوم - Las Comidas del Día', 'الفطور والغداء والعشاء', 'اليوم الإسباني فيه ثلاث وجبات: el desayuno (الفطور)، la comida (الغداء، عادة الثانية)، la cena (العشاء، متأخراً).', '[{"es":"el desayuno","ar":"الفطور"},{"es":"la comida","ar":"الغداء"},{"es":"la cena","ar":"العشاء"},{"es":"la merienda","ar":"وجبة العصر الخفيفة"}]'::jsonb, '[{"es":"La cena en España es a las nueve.","ar":"العشاء في إسبانيا في التاسعة."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('c939f00f-6beb-5ce6-a379-44a2fe350906', '38d16ca0-8cbb-55bb-a392-fdc249472a82', 'في المطبخ - En la Cocina', 'أدوات وأفعال المطبخ', 'أدوات المطبخ الشائعة: la olla (القدر)، el plato (الطبق). وأفعاله الأساسية: cocinar (يطبخ) وcortar (يقطع).', '[{"es":"la olla","ar":"القدر"},{"es":"el plato","ar":"الطبق"},{"es":"cocinar","ar":"يطبخ"},{"es":"cortar","ar":"يقطع"}]'::jsonb, '[{"es":"Corto las verduras y cocino la sopa.","ar":"أقطع الخضار وأطبخ الشوربة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('54fd4c2a-d50d-57a8-9c5e-46023a59d524', '789b7bba-55ab-589b-8822-f207f16ee120', 'الطلب في المطعم - Hacer un Pedido', 'كيف تطلب بطريقة صحيحة', 'للطلب بأدب نستخدم quisiera (أودّ) أو para mí (لي): Quisiera una sopa, por favor. Para mí, un pollo.', '[{"es":"quisiera","ar":"أودّ"},{"es":"para mí","ar":"لي"},{"es":"la carta","ar":"قائمة الطعام"},{"es":"el camarero","ar":"النادل"}]'::jsonb, '[{"es":"Quisiera la carta, por favor.","ar":"أودّ قائمة الطعام، من فضلك."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('9b0183e1-f19c-5ed8-adae-ab90d1db083b', '789b7bba-55ab-589b-8822-f207f16ee120', 'الفاتورة والدفع - La Cuenta', 'طلب الفاتورة والدفع', 'لطلب الفاتورة: La cuenta, por favor. وفي إسبانيا يقسم الأصدقاء الفاتورة أحياناً: a escote (على Sharing).', '[{"es":"la cuenta","ar":"الفاتورة"},{"es":"pagar","ar":"يدفع"},{"es":"la propina","ar":"البقشيش"},{"es":"a escote","ar":"على حساب الجميع"}]'::jsonb, '[{"es":"La cuenta, por favor. ¿Puedo pagar con tarjeta?","ar":"الفاتورة، من فضلك. هل أستطيع الدفع بالبطاقة؟"}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('e126bc09-595a-5d69-94f4-185cea531e36', '789b7bba-55ab-589b-8822-f207f16ee120', 'التعبير عن الذوق - El Sabor', 'وصف طعم الأكل', 'لوصف الطعم: delicioso (لذيذ)، salado (مالح)، dulce (حلو)، picante (حار): La paella está deliciosa.', '[{"es":"delicioso","ar":"لذيذ"},{"es":"salado","ar":"مالح"},{"es":"dulce","ar":"حلو المذاق"},{"es":"picante","ar":"حار"}]'::jsonb, '[{"es":"Esta sopa está muy salada.","ar":"هذه الشوربة مالحة جداً."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('9a8822d3-b43a-5ffb-b236-877822d702c4', 'fd29dd61-06b7-530d-b01b-e3c7f8214aea', 'الأرقام 1-100 - Números 1-100', 'بنية الأرقام الإسبانية', 'من 1-15 أسماء خاصة (uno, dos... quince)، ثم dieciséis، veinte، treinta... وتُركب: veintiuno، treinta y cinco.', '[{"es":"quince","ar":"خمسة عشر"},{"es":"veinte","ar":"عشرون"},{"es":"treinta y cinco","ar":"خمسة وثلاثون"},{"es":"cien","ar":"مئة"}]'::jsonb, '[{"es":"Tengo veinticinco años.","ar":"عمري خمس وعشرون سنة."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('ae155c9c-5964-587a-b00e-74b8ef4c501c', 'fd29dd61-06b7-530d-b01b-e3c7f8214aea', 'الأسعار - Los Precios', 'السؤال عن السعر وقراءته', 'للسؤال عن الثمن: ¿Cuánto cuesta? أو ¿Cuánto es? والإجابة: Son veinte euros (عشرون يورو).', '[{"es":"¿Cuánto cuesta?","ar":"كم يكلف؟"},{"es":"el euro","ar":"اليورو"},{"es":"caro","ar":"غالٍ"},{"es":"barato","ar":"رخيص"}]'::jsonb, '[{"es":"¿Cuánto cuesta este libro? — Diez euros.","ar":"كم يكلف هذا الكتاب؟ — عشرة يورو."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('cab9fdbc-4272-5877-9dfa-826b1a92c3cb', 'fd29dd61-06b7-530d-b01b-e3c7f8214aea', 'الحساب البسيط - Cálculo Simple', 'جمع وطرح بالأرقام', 'أفعال الحساب: sumar (يجمع)، restar (يطرح)، multiplicar (يضرب): Dos más dos son cuatro.', '[{"es":"sumar","ar":"يجمع"},{"es":"restar","ar":"يطرح"},{"es":"más","ar":"زائد"},{"es":"menos","ar":"ناقص"}]'::jsonb, '[{"es":"Diez menos tres son siete.","ar":"عشرة ناقص ثلاثة يساوي سبعة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('555bb77c-23aa-50bd-8f75-ef7dd50a65b9', '886ab92d-e0b4-5288-aa1a-f3ab9c0cab89', 'قراءة الساعة - Decir la Hora', 'كيف تسأل وتجيب عن الساعة', 'للسؤال: ¿Qué hora es? وللإجابة نستخدم فعل ser: Es la una (الواحدة)، Son las tres (الثالثة). وللدقائق: y cuarto، y media، menos cuarto.', '[{"es":"¿Qué hora es?","ar":"كم الساعة؟"},{"es":"Son las tres","ar":"الساعة الثالثة"},{"es":"y media","ar":"ونصف"},{"es":"menos cuarto","ar":"إلا ربعاً"}]'::jsonb, '[{"es":"Son las cuatro y media.","ar":"الساعة الرابعة والنصف."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('759f3ba4-f088-5247-8bfe-4e81d3d693a4', '886ab92d-e0b4-5288-aa1a-f3ab9c0cab89', 'أجزاء اليوم - Partes del Día', 'الصباح والظهيرة والمساء والليل', 'أجزاء اليوم: la mañana (الصباح)، la tarde (بعد الظهر)، la noche (الليل). مع التحيات: Buenos días صباحاً، Buenas tardes عصراً، Buenas noches ليلاً.', '[{"es":"la mañana","ar":"الصباح"},{"es":"la tarde","ar":"بعد الظهر"},{"es":"la noche","ar":"الليل"},{"es":"al mediodía","ar":"في الظهيرة"}]'::jsonb, '[{"es":"Estudio por la mañana y trabajo por la tarde.","ar":"أدرس صباحاً وأعمل بعد الظهر."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('d950b025-d52c-521e-ad18-37c298198694', '886ab92d-e0b4-5288-aa1a-f3ab9c0cab89', 'المواعيد - Las Citas', 'ترتيب المواعيد والأوقات', 'لتحديد موعد: ¿A qué hora? (في أي ساعة؟)، a las cinco (في الخامسة). للسؤال عن اليوم: ¿Qué día? والترتيب: antes (قبل)، después (بعد).', '[{"es":"¿A qué hora?","ar":"في أي ساعة؟"},{"es":"a las cinco","ar":"في الخامسة"},{"es":"antes","ar":"قبل"},{"es":"después","ar":"بعد"}]'::jsonb, '[{"es":"¿A qué hora nos vemos? — A las seis.","ar":"متى نلتقي؟ — في السادسة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('b48adf7a-7fd8-5104-bc07-1a898a5f55f6', '9f3579d0-48d0-5ca1-bd90-7df00d8b9291', 'أيام الأسبوع - Días de la Semana', 'أسماء الأيام وقواعد استخدامها', 'أيام الأسبوع لا تُكتب بحرف كبير: lunes، martes... ومع أداة التعريف: el lunes (يوم الاثنين)، los lunes (كل اثنين).', '[{"es":"lunes","ar":"الاثنين"},{"es":"miércoles","ar":"الأربعاء"},{"es":"viernes","ar":"الجمعة"},{"es":"domingo","ar":"الأحد"}]'::jsonb, '[{"es":"Los lunes trabajo desde casa.","ar":"أيام الاثنين أعمل من المنزل."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('3446a897-2e9c-5d1c-bfe6-38d011c978ff', '9f3579d0-48d0-5ca1-bd90-7df00d8b9291', 'الأشهر والفصول - Meses y Estaciones', 'أشهر السنة', 'الأشهر: enero، febrero، marzo... ولا تُكتب بحرف كبير. للتاريخ: el cinco de mayo (الخامس من مايو).', '[{"es":"enero","ar":"يناير"},{"es":"abril","ar":"أبريل"},{"es":"julio","ar":"يوليو"},{"es":"diciembre","ar":"ديسمبر"}]'::jsonb, '[{"es":"Mi cumpleaños es el diez de agosto.","ar":"عيد ميلادي هو العاشر من أغسطس."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('5f11205f-19b6-5279-a440-d1f144190793', '9f3579d0-48d0-5ca1-bd90-7df00d8b9291', 'المناسبات - Fechas Especiales', 'التواريخ المهمة والاحتفال بها', 'للمناسبات: el Año Nuevo (رأس السنة)، la Navidad (عيد الميلاد)، mi cumpleaños (عيد ميلادي): ¡Feliz cumpleaños!', '[{"es":"el cumpleaños","ar":"عيد الميلاد"},{"es":"el Año Nuevo","ar":"رأس السنة"},{"es":"la Navidad","ar":"عيد الميلاد"},{"es":"¡Feliz cumpleaños!","ar":"عيد ميلاد سعيد!"}]'::jsonb, '[{"es":"El Año Nuevo empieza el uno de enero.","ar":"رأس السنة يبدأ في الأول من يناير."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('460d4898-7210-5abf-a58b-83ee7b520040', '415e6051-298e-5c47-84fb-748877a1557c', 'حالة الجو - ¿Qué Tiempo Hace?', 'وصف الطقس بفعل hacer', 'الطقس يُوصف بفعل hacer: Hace sol (مشمس)، Hace frío (بارد)، Hace calor (حار). وإنما يتغير بعضها: Está nublado (غائم)، Llueve (تمطر).', '[{"es":"Hace sol","ar":"الجو مشمس"},{"es":"Hace frío","ar":"الجو بارد"},{"es":"Hace calor","ar":"الجو حار"},{"es":"Llueve","ar":"إنها تمطر"}]'::jsonb, '[{"es":"Hoy hace mucho calor en Sevilla.","ar":"الجو حار جداً اليوم في إشبيلية."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('fb1d7a01-b56f-5eb6-9060-ef2cdd7657dc', '415e6051-298e-5c47-84fb-748877a1557c', 'الفصول الأربعة - Las Cuatro Estaciones', 'أسماء الفصول وطقسها', 'الفصول: la primavera (الربيع)، el verano (الصيف)، el otoño (الخريف)، el invierno (الشتاء): En verano hace calor.', '[{"es":"la primavera","ar":"الربيع"},{"es":"el verano","ar":"الصيف"},{"es":"el otoño","ar":"الخريف"},{"es":"el invierno","ar":"الشتاء"}]'::jsonb, '[{"es":"En invierno nieva en las montañas.","ar":"في الشتاء تثلج في الجبال."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('f583f38e-9db5-5a1c-8d16-8f08b5eb1d6c', '415e6051-298e-5c47-84fb-748877a1557c', 'الملابس والطقس - Vestirse Según el Clima', 'ربط اللبس بالطقس', 'نربط اللبس بالطقس: Si llueve, llevo paraguas (إن أمطرت أحمل مظلة). وparaguas للمطر وgafas de sol للشمس.', '[{"es":"el paraguas","ar":"المظلة"},{"es":"las gafas de sol","ar":"نظارة الشمس"},{"es":"el abrigo","ar":"المعطف"},{"es":"la sombrilla","ar":"مظلة الشمس"}]'::jsonb, '[{"es":"Llevo paraguas porque va a llover.","ar":"أحمل مظلة لأنها ستمطر."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('db9048f0-17e2-5c63-88a2-a880d776aaeb', 'a09ec708-ae09-559a-ba5e-001423739932', 'غرف البيت - Las Habitaciones', 'أسماء غرف المنزل', 'غرف البيت: la cocina (المطبخ)، el salón (غرفة الجلوس)، el dormitorio (غرفة النوم)، el baño (الحمام): Estoy en mi habitación.', '[{"es":"la cocina","ar":"المطبخ"},{"es":"el salón","ar":"غرفة الجلوس"},{"es":"el dormitorio","ar":"غرفة النوم"},{"es":"el baño","ar":"الحمام"}]'::jsonb, '[{"es":"La cocina está al lado del salón.","ar":"المطبخ بجانب غرفة الجلوس."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('ec876b85-05d1-5d06-b246-3932e7565fc4', 'a09ec708-ae09-559a-ba5e-001423739932', 'الأثاث - Los Muebles', 'أثاث البيت', 'الأثاث: la mesa، la silla، la cama، el sofá: El sofá está en el salón. وla lámpara للإضاءة.', '[{"es":"la mesa","ar":"الطاولة"},{"es":"la cama","ar":"السرير"},{"es":"el sofá","ar":"الأريكة"},{"es":"la lámpara","ar":"المصباح"}]'::jsonb, '[{"es":"Mis libros están en la mesa.","ar":"كتبي على الطاولة."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('ef8a6c49-b8f5-5d14-971c-23022e7c1ba4', 'a09ec708-ae09-559a-ba5e-001423739932', 'المهام المنزلية - Las Tareas de Casa', 'أعمال البيت اليومية', 'المهام المنزلية: lavar los platos (غسل الأطباق)، barrer (يكنس)، planchar (يكوي): Hoy me toca cocinar (اليوم دوري أن أطبخ).', '[{"es":"lavar los platos","ar":"غسل الأطباق"},{"es":"barrer","ar":"يكنس"},{"es":"plancha","ar":"يكوي/الكوي"},{"es":"la basura","ar":"النفايات"}]'::jsonb, '[{"es":"Saco la basura todos los días.","ar":"أُخرج النفايات كل يوم."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('8ddf47bb-e5eb-58a9-b43e-edad0fd92148', 'f963ef9a-1211-5368-b633-02db4ec0d0ea', 'أماكن المدينة - Lugares de la Ciudad', 'المواقع المهمة في المدينة', 'أماكن أساسية: la plaza (الساحة)، el parque (الحديقة)، la iglesia (الكنيسة)، el ayuntamiento (البلدية): El parque está cerca.', '[{"es":"la plaza","ar":"الساحة"},{"es":"el parque","ar":"الحديقة العامة"},{"es":"el ayuntamiento","ar":"البلدية"},{"es":"la biblioteca","ar":"المكتبة"}]'::jsonb, '[{"es":"Nos vemos en la plaza mayor.","ar":"نتقابل في الساحة الكبرى."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('c31e2799-8911-5aa1-8e6b-ade043c68025', 'f963ef9a-1211-5368-b633-02db4ec0d0ea', 'الاتجاهات - Las Direcciones', 'كيف تسأل عن الطريق وتجيب', 'للسؤال: ¿Dónde está...? وللإجابة: a la derecha (يميناً)، a la izquierda (يساراً)، todo recto (مستقيماً): Gire a la derecha.', '[{"es":"¿Dónde está...?","ar":"أين يقع...؟"},{"es":"a la derecha","ar":"إلى اليمين"},{"es":"a la izquierda","ar":"إلى اليسار"},{"es":"todo recto","ar":"مستقيماً"}]'::jsonb, '[{"es":"Siga todo recto y gire a la izquierda.","ar":"اتبع مستقيماً ثم انعطف يساراً."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('4ee9f8df-9fd8-5ec6-b60d-532bfda8ac4c', 'f963ef9a-1211-5368-b633-02db4ec0d0ea', 'قريب وبعيد - Cerca y Lejos', 'المسافات والمواقع النسبية', 'لوصف المسافة: cerca (قريب)، lejos (بعيد)، al lado de (بجانب)، enfrente de (مقابل): El banco está enfrente del mercado.', '[{"es":"cerca","ar":"قريب"},{"es":"lejos","ar":"بعيد"},{"es":"al lado de","ar":"بجانب"},{"es":"enfrente de","ar":"مقابل"}]'::jsonb, '[{"es":"Mi casa está cerca de la estación.","ar":"بيتي قريب من المحطة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('cd187a91-4c50-5dc7-879b-2819e847bb3d', '8229a33a-030e-58eb-9256-56c77fc140a0', 'المواصلات - Medios de Transporte', 'أسماء وسائل التنقل', 'وسائل النقل: el autobús (الباص)، el metro (المترو)، el tren (القطار)، el avión (الطائرة): Voy al trabajo en metro.', '[{"es":"el autobús","ar":"الباص"},{"es":"el metro","ar":"المترو"},{"es":"el tren","ar":"القطار"},{"es":"el avión","ar":"الطائرة"}]'::jsonb, '[{"es":"Voy al centro en autobús.","ar":"أذهب إلى المركز بالباص."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('4500df43-8102-5925-b89a-3d839aa7ff87', '8229a33a-030e-58eb-9256-56c77fc140a0', 'التذاكر - Los Billetes', 'شراء التذاكر والسؤال عنها', 'لشراء تذكرة: Un billete a Madrid, por favor. وأنواعها: de ida (ذهاب)، de ida y vuelta (ذهاب وعودة).', '[{"es":"el billete","ar":"التذكرة"},{"es":"de ida","ar":"ذهاب فقط"},{"es":"de ida y vuelta","ar":"ذهاب وعودة"},{"es":"la parada","ar":"الموقف"}]'::jsonb, '[{"es":"Un billete de ida y vuelta a Valencia.","ar":"تذكرة ذهاب وعودة إلى بلنسية."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('5eff7038-a37b-54b6-8be8-e53904fb7302', '8229a33a-030e-58eb-9256-56c77fc140a0', 'رحلة قصيرة - Un Viaje Corto', 'وصف تنقّل يومي', 'لوصف التنقل: coger (يأخذ/يركب في إسبانيا)، bajar en... (ينزل في...): Cogo el metro y bajo en Sol.', '[{"es":"coger","ar":"يأخذ/يركب"},{"es":"subir","ar":"يصعد"},{"es":"bajar","ar":"ينزل"},{"es":"el andén","ar":"الرصيف"}]'::jsonb, '[{"es":"Subo al autobús en la plaza.","ar":"أركب الباص في الساحة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('3e0296c3-d3b9-5747-8877-77997f64cb3f', '7dd5cd19-2867-52e8-b034-e233f3c6a78c', 'أفراد العائلة - Miembros de la Familia', 'أسماء العائلة المباشرة', 'العائلة المباشرة: el padre، la madre، el hermano، la hermana، los hijos: Tengo dos hermanas.', '[{"es":"el padre","ar":"الأب"},{"es":"la madre","ar":"الأم"},{"es":"el hermano","ar":"الأخ"},{"es":"la hermana","ar":"الأخت"}]'::jsonb, '[{"es":"Mi hermana menor estudia en la universidad.","ar":"أختي الصغرى تدرس في الجامعة."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('39d5bce2-1b6d-5259-b3f5-717cf652a74b', '7dd5cd19-2867-52e8-b034-e233f3c6a78c', 'الأقارب - Los Parientes', 'الأجداد والأعمام والأبناء', 'الأقارب الممتدون: el abuelo/la abuela (الجد/الجدة)، el tío/la tía (العم والخال)، el primo/la prima (ابن/بنت العم والخال).', '[{"es":"el abuelo","ar":"الجد"},{"es":"la abuela","ar":"الجدة"},{"es":"el tío","ar":"العم/الخال"},{"es":"el primo","ar":"ابن العم/الخال"}]'::jsonb, '[{"es":"Mi abuela cocina muy bien.","ar":"جدتي تطبخ جيداً جداً."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('6f836949-cd22-5f90-a1d7-ef08cbe23849', '7dd5cd19-2867-52e8-b034-e233f3c6a78c', 'الحالة الاجتماعية - Estado Civil', 'متزوج وعازب ووصف العائلة', 'لوصف الحالة: casado (متزوج)، soltero (أعزب)، hijos: ¿Estás casado? — No, estoy soltero. وsuegra لحماتها.', '[{"es":"casado","ar":"متزوج"},{"es":"soltero","ar":"أعزب"},{"es":"los hijos","ar":"الأبناء"},{"es":"la suegra","ar":"الحمات/الوالدة الزوجة"}]'::jsonb, '[{"es":"Mi hermano está casado y tiene dos hijos.","ar":"أخي متزوج وعنده ولدان."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('0d58d11b-1ed1-5d1b-bc6e-6942d20117a0', 'e8480b9d-5114-56c8-a89d-06e9472741bb', 'أعضاء الجسم - Las Partes del Cuerpo', 'أسماء أعضاء الجسم الأساسية', 'أعضاء الجسم: la cabeza، el brazo، la pierna، el corazón: Me duele el brazo (ذراعي يؤلمني).', '[{"es":"la cabeza","ar":"الرأس"},{"es":"el brazo","ar":"الذراع"},{"es":"la pierna","ar":"الساق"},{"es":"el corazón","ar":"القلب"}]'::jsonb, '[{"es":"Corro todos los días para el corazón.","ar":"أركض كل يوم من أجل القلب."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('040173fc-5c6f-5793-b219-b60a8ca75e5b', 'e8480b9d-5114-56c8-a89d-06e9472741bb', 'عند الطبيب - En el Médico', 'وصف الأعراض البسيطة', 'لوصف الألم نستخدم doler: Me duele la garganta (حلقي يؤلمني). وللسؤال: ¿Qué le pasa? (ما بك؟).', '[{"es":"me duele","ar":"يؤلمني"},{"es":"la garganta","ar":"الحلق"},{"es":"la fiebre","ar":"الحمى"},{"es":"el jarabe","ar":"الشراب الطبي"}]'::jsonb, '[{"es":"Tengo fiebre y me duele la cabeza.","ar":"عندي حمى ورأسي يؤلمني."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('5653f959-4e1b-5da3-890e-1d17f12d0ef6', 'e8480b9d-5114-56c8-a89d-06e9472741bb', 'عادات صحية - Hábitos Saludables', 'نصائح الصحة اليومية', 'عادات صحية: hacer ejercicio (يمارس رياضة)، dormir bien (ينام جيداً)، beber agua (يشرب ماء): Es importante dormir ocho horas.', '[{"es":"hacer ejercicio","ar":"يمارس الرياضة"},{"es":"dormir bien","ar":"ينام جيداً"},{"es":"beber agua","ar":"يشرب الماء"},{"es":"la salud","ar":"الصحة"}]'::jsonb, '[{"es":"Bebo dos litros de agua al día.","ar":"أشرب لترين من الماء يومياً."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('c4156e05-4bdc-542a-8c4a-db084956a62e', 'bf583bf1-d0e4-5605-800a-3281f5e883e8', 'قطع الملابس - Prendas de Ropa', 'أسماء الملابس الشائعة', 'قطع الملابس: la camisa، los pantalones، el vestido، los zapatos، la chaqueta: Llevo una camisa azul.', '[{"es":"la camisa","ar":"القميص"},{"es":"los pantalones","ar":"البنطال"},{"es":"el vestido","ar":"الفستان"},{"es":"los zapatos","ar":"الحذاء"}]'::jsonb, '[{"es":"Compré unos zapatos nuevos.","ar":"اشتريت حذاءً جديداً."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('20482543-5192-54cb-a9d2-158f39943c75', 'bf583bf1-d0e4-5605-800a-3281f5e883e8', 'المقاسات - Las Tallas', 'المقاسات والتجربة في المتجر', 'للسؤال عن المقاس: ¿Qué talla necesita? والمقاسات: pequeño (S)، mediano (M)، grande (L). وللتجربة: ¿Puedo probármelo?', '[{"es":"la talla","ar":"المقاس"},{"es":"pequeño","ar":"صغير"},{"es":"mediano","ar":"متوسط"},{"es":"probármelo","ar":"أجربه عليّ"}]'::jsonb, '[{"es":"¿Puedo probarme esta camisa? Es talla mediana.","ar":"هل أجرب هذا القميص؟ مقاسه متوسط."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('b31b6b37-8d73-509f-90bf-36127127d297', 'bf583bf1-d0e4-5605-800a-3281f5e883e8', 'الدفع في المتجر - Pagar en la Tienda', 'طرق الدفع والفواتير', 'للدفع: ¿Puedo pagar con tarjeta? (بالبطاقة؟)، en efectivo (نقداً)، el recibo (الإيصال): Pago en efectivo.', '[{"es":"en efectivo","ar":"نقداً"},{"es":"con tarjeta","ar":"بالبطاقة"},{"es":"el recibo","ar":"الإيصال"},{"es":"el cambio","ar":"الباقي"}]'::jsonb, '[{"es":"Aquí tiene su recibo y el cambio.","ar":"تفضل إيصالك والباقي."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('cff612b1-33d2-5281-880a-c0fe8af859ea', 'c3dba10a-c5de-5529-928d-7d7441f2c288', 'حيوانات الأليفة - Las Mascotas', 'أسماء الحيوانات المنزلية', 'حيوانات الأليفة: el perro، el gato، el pájaro، el pez: Tengo un gato que se llama Luna.', '[{"es":"el perro","ar":"الكلب"},{"es":"el gato","ar":"القط"},{"es":"el pájaro","ar":"الطائر"},{"es":"el pez","ar":"السمكة"}]'::jsonb, '[{"es":"Mi perro es muy cariñoso.","ar":"كلبي ودود جداً."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('55d7084c-4754-5ec8-a40f-089817090a2e', 'c3dba10a-c5de-5529-928d-7d7441f2c288', 'حيوانات المزرعة - Animales de Granja', 'حيوانات المزرعة', 'حيوانات المزرعة: la vaca (البقرة)، el caballo (الحصان)، la oveja (النعجة)، la gallina (الدجاجة).', '[{"es":"la vaca","ar":"البقرة"},{"es":"el caballo","ar":"الحصان"},{"es":"la oveja","ar":"النعجة"},{"es":"la gallina","ar":"الدجاجة"}]'::jsonb, '[{"es":"La vaca da leche.","ar":"البقرة تعطي حليباً."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, chapter_id, title, description, content, vocabulary, examples, pronunciation, order_num, is_free, xp_reward, duration, createdAt) VALUES
('c4f8fd7c-a3ff-564b-af6d-11e89ab07826', 'c3dba10a-c5de-5529-928d-7d7441f2c288', 'الحياة الفطرية - Animales Salvajes', 'حيوانات الغابة والبرية', 'حيوانات برية: el león (الأسد)، el oso (الدب)، el lobo (الذئب)، el mono (القرد): El león vive en la sabana.', '[{"es":"el león","ar":"الأسد"},{"es":"el oso","ar":"الدب"},{"es":"el lobo","ar":"الذئب"},{"es":"el mono","ar":"القرد"}]'::jsonb, '[{"es":"En el zoológico vimos monos y osos.","ar":"في حديقة الحيوان رأينا قروداً ودببة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('e6dfc98b-1c07-5a50-8d40-8ab859453e0d', '762889ef-1e07-5c34-82d4-1f60ba45e561', 'المهن الشائعة - Profesiones Comunes', 'أسماء الوظائف', 'مهن شائعة: el médico، el profesor، el ingeniero، el panadero: Mi padre es ingeniero.', '[{"es":"el médico","ar":"الطبيب"},{"es":"el profesor","ar":"الأستاذ"},{"es":"el ingeniero","ar":"المهندس"},{"es":"el panadero","ar":"الخبّاز"}]'::jsonb, '[{"es":"Quiero ser médico en el futuro.","ar":"أريد أن أصبح طبيباً في المستقبل."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('dab1a580-e1f2-56a7-8a3a-7215254caadc', '762889ef-1e07-5c34-82d4-1f60ba45e561', 'مكان العمل - El Lugar de Trabajo', 'أماكن العمل', 'أماكن العمل: la oficina (المكتب)، el hospital (المستشفى)، la fábrica (المصنع)، la tienda (المتجر): Trabajo en una oficina.', '[{"es":"la oficina","ar":"المكتب"},{"es":"el hospital","ar":"المستشفى"},{"es":"la fábrica","ar":"المصنع"},{"es":"el taller","ar":"الورشة"}]'::jsonb, '[{"es":"Mi madre trabaja en un hospital.","ar":"أمي تعمل في مستشفى."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('e0032097-66db-5e7c-8f8a-a82d9d1b6c5a', '762889ef-1e07-5c34-82d4-1f60ba45e561', 'يوم العمل - El Día de Trabajo', 'وصف يوم العمل', 'لوصف العمل: trabajar (يعمل)، la reunión (الاجتماع)، el jefe (المدير): Tengo una reunión a las diez.', '[{"es":"trabajar","ar":"يعمل"},{"es":"la reunión","ar":"الاجتماع"},{"es":"el jefe","ar":"المدير"},{"es":"el sueldo","ar":"الراتب"}]'::jsonb, '[{"es":"Mi jefe es muy amable.","ar":"مديري لطيف جداً."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('ad8df892-7265-5b6c-b5b8-4cd6698aa749', 'd88bf55d-18bd-5b66-8586-923b7771b122', 'أنشطة يومية - Actividades Diarias', 'هوايات بسيطة شائعة', 'هوايات شائعة: leer (يقرأ)، nadar (يسبح)، caminar (يمشي)، escuchar música: Me gusta leer por la noche.', '[{"es":"leer","ar":"يقرأ"},{"es":"nadar","ar":"يسبح"},{"es":"caminar","ar":"يمشي"},{"es":"descansar","ar":"يستريح"}]'::jsonb, '[{"es":"Los domingos camino por el parque.","ar":"أيام الأحد أمشي في الحديقة."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('5aee2ea9-2412-54a0-bdba-199b3847b6e1', 'd88bf55d-18bd-5b66-8586-923b7771b122', 'الموسيقى والرسم - Música y Dibujo', 'هوايات فنية', 'هوايات فنية: tocar la guitarra (يعزف الغيتار)، dibujar (يرسم)، cantar (يغني): Canto en la ducha.', '[{"es":"tocar la guitarra","ar":"يعزف الغيتار"},{"es":"dibujar","ar":"يرسم"},{"es":"cantar","ar":"يغني"},{"es":"bailar","ar":"يرقص"}]'::jsonb, '[{"es":"Mi hermana canta y baila muy bien.","ar":"أختي تغني وترقص جيداً جداً."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
