('434618f0-f832-51ef-af10-eb78db49a6bb', 'fcd5d766-4015-51b4-bf49-ecce4c5f11c4', 'الأحلام - Los Sueños', 'التعبير عن الطموح', 'للأحلام: mi sueño es... (حلمي هو...)، me gustaría (أودّ): Mi sueño es hablar español con fluidez.', '[{"es":"el sueño","ar":"الحلم"},{"es":"me gustaría","ar":"أودّ"},{"es":"con fluidez","ar":"بطلاقة"},{"es":"el objetivo","ar":"الهدف"}]'::jsonb, '[{"es":"Me gustaría trabajar en España algún día.","ar":"أودّ العمل في إسبانيا يوماً ما."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('0628982c-2056-5cd5-9d60-9212f6b5e371', '13d88358-cdf7-51ed-9bfd-1665c3c36582', 'المكونات - Los Ingredientes', 'مكونات الوصفة', 'مكونات أساسية: el aceite (الزيت)، la sal (الملح)، el azúcar (السكر)، la harina (الطحين): Añade un poco de sal.', '[{"es":"el aceite","ar":"الزيت"},{"es":"la sal","ar":"الملح"},{"es":"el azúcar","ar":"السكر"},{"es":"la harina","ar":"الطحين"}]'::jsonb, '[{"es":"Añade dos cucharadas de aceite.","ar":"أضف ملعقتين من الزيت."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('9ee102e5-5b5a-5f36-99a7-4e87c5a26b1e', '13d88358-cdf7-51ed-9bfd-1665c3c36582', 'خطوات الوصفة - Pasos de la Receta', 'أفعال الطبخ بالترتيب', 'أفعال الطبخ: freír (يقلي)، hervir (يغلي)، mezclar (يمزج)، hornear (يخبز): Mezcla todo y hornea media hora.', '[{"es":"freír","ar":"يقلي"},{"es":"hervir","ar":"يغلي"},{"es":"mezclar","ar":"يمزج"},{"es":"hornear","ar":"يخبز في الفرن"}]'::jsonb, '[{"es":"Hierve el agua antes de añadir la pasta.","ar":"اغلِ الماء قبل إضافة المعكرونة."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('d4b02b07-d17e-5896-a6aa-e64bcd241f26', '13d88358-cdf7-51ed-9bfd-1665c3c36582', 'التعبير عن الذوق - Decir qué nos Gusta', 'وصف طبق بأدب', 'للتعليق على الأكل: Está buenísimo (لذيذ جداً)، un poco soso (بلا طعم): Esta receta está buenísima.', '[{"es":"buenísimo","ar":"لذيذ جداً"},{"es":"soso","ar":"بلا مذاق"},{"es":"tierno","ar":"طري"},{"es":"la receta","ar":"الوصفة"}]'::jsonb, '[{"es":"La carne está muy tierna.","ar":"اللحم طري جداً."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()) ON CONFLICT DO NOTHING;
