('9de52f96-c791-5e3a-a0dd-24e78d5c5a78', '71d524f7-6fa5-5d18-916d-6b7dc8d1989e', 'الطقس والأنشطة - Clima y Planes', 'خطة اليوم حسب الطقس', 'نخطط حسب الطقس: Si hace buen tiempo, iremos a la playa (إن كان الجو جميلاً سنذهب للشاطئ).', '[{"es":"si hace buen tiempo","ar":"إن كان الجو جميلاً"},{"es":"cancelar","ar":"يلغي"},{"es":"aplazar","ar":"يؤجل"},{"es":"el plan b","ar":"الخطة البديلة"}]'::jsonb, '[{"es":"Si llueve, cancelamos el picnic.","ar":"إن أمطرت نلغي النزهة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
