('792ab26c-dd56-5268-9309-611d84e9e833', '247cdcb3-51d7-5353-8c90-2720019639f8', 'الادخار - Ahorrar Dinero', 'بناء عادة الادخار', 'الادخار: guardar dinero cada mes، el colchón (الاحتياطي): Es recomendable ahorrar el diez por ciento del sueldo.', '[{"es":"ahorrar","ar":"يدّخر"},{"es":"el colchón financiero","ar":"الاحتياطي المالي"},{"es":"la hucha","ar":"حصالة النقود"},{"es":"el interés","ar":"الفائدة"}]'::jsonb, '[{"es":"Meto cincuenta euros en la hucha cada mes.","ar":"أضع خمسين يورو في الحصالة شهرياً."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('7a43ff81-c7dd-5f45-a03c-fbf911f213a8', '247cdcb3-51d7-5353-8c90-2720019639f8', 'الديون - Las Deudas', 'القرض وسداده', 'الديون: pedir un préstamo (يطلب قرضاً)، devolver las cuotas (يسدد الأقساط): Pedí un préstamo para el coche.', '[{"es":"el préstamo","ar":"القرض"},{"es":"la cuota","ar":"القسط"},{"es":"la deuda","ar":"الدَّين"},{"es":"el banco","ar":"البنك"}]'::jsonb, '[{"es":"Pago la cuota del préstamo el día cinco.","ar":"أدفع قسط القرض في الخامس."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('afcc07fd-ea7a-5e95-a899-e5b69c9b9e94', '02d86f52-2303-5831-b5e1-9049ed6d082c', 'التعبير عن الضغط - Hablar del Estrés', 'وصف الشعور بالضغط', 'الضغط: estar estresado (متضغط)، el estrés del trabajo: Llevo semanas estresado por los exámenes.', '[{"es":"el estrés","ar":"الإجهاد"},{"es":"agobiado","ar":"مثقل بالضغط"},{"es":"relajarse","ar":"يسترخي"},{"es":"la presión","ar":"الضغط"}]'::jsonb, '[{"es":"Necesito relajarme este fin de semana.","ar":"أحتاج الاسترخاء نهاية هذا الأسبوع."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('1ed049ef-122a-562b-90bf-c4e63ab78f98', '02d86f52-2303-5831-b5e1-9049ed6d082c', 'التوازن بين العمل والحياة - Equipo Vida-Trabajo', 'التوازن الصحي', 'التوازن: conciliar el trabajo y la vida personal (الموازنة): Hacer deporte me ayuda a conciliar mi día.', '[{"es":"conciliar","ar":"يوازن بين"},{"es":"el equilibrio","ar":"التوازن"},{"es":"la rutina","ar":"الروتين"},{"es":"el descanso","ar":"الراحة"}]'::jsonb, '[{"es":"El equilibrio entre trabajo y descanso es clave.","ar":"التوازن بين العمل والراحة أساسي."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
