('02e6ce85-bfbb-5cc9-bb49-bfcf6e7e3585', 'ea2815d7-e5ea-52de-af26-3350ec4536e5', 'الدورات التدريبية - Los Cursos', 'اختيار دورة', 'الدورات: el curso online، la inscripción (التسجيل)، el temario (المحتوى): Me he inscrito en un curso de fotografía.', '[{"es":"la inscripción","ar":"التسجيل في دورة"},{"es":"el temario","ar":"محتوى الدورة"},{"es":"el profesor","ar":"المدرّب"},{"es":"la plataforma","ar":"منصة التعلم"}]'::jsonb, '[{"es":"El temario del curso tiene diez módulos.","ar":"محتوى الدورة فيه عشرة وحدات."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
