('dbad3494-9f09-5055-9808-24a62144968d', 'ea2815d7-e5ea-52de-af26-3350ec4536e5', 'الشهادات - Los Certificados', 'إثبات المهارة', 'الشهادات: el certificado، el diploma، acreditar (يُثبت): El examen DELE acredita tu nivel de español.', '[{"es":"el certificado","ar":"الشهادة"},{"es":"acreditar","ar":"يثبت رسمياً"},{"es":"el nivel B1","ar":"مستوى B1"},{"es":"la convocatoria","ar":"دورة الامتحان"}]'::jsonb, '[{"es":"Me presento a la convocatoria de mayo.","ar":"أتقدم في دورة امتحان مايو."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
