('86dcc1e5-0812-51cc-a6ea-5985a0361ac1', '33f2a742-504e-5b39-801b-63180dbd4b02', 'التجربة - El Experimento', 'إجراء التجربة', 'التجربة: el laboratorio (المختبر)، el ensayo clínico (التجربة السريرية)، reproducible (قابل للتكرار): Los resultados son reproducibles en otros laboratorios.', '[{"es":"el laboratorio","ar":"المختبر"},{"es":"el ensayo clínico","ar":"التجربة السريرية"},{"es":"reproducible","ar":"قابل للتكرار"},{"es":"el equipo de investigación","ar":"فريق البحث"}]'::jsonb, '[{"es":"El ensayo clínico dura tres años.","ar":"التجربة السريرية تستغرق ثلاث سنوات."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('db2e305d-b8aa-5ccd-a2bd-052b78c0280c', '33f2a742-504e-5b39-801b-63180dbd4b02', 'النتائج والنشر - Resultados y Publicación', 'خلاصة البحث', 'النتائج: los hallazgos (الاستنتاجات)، publicar en una revista científica: Los hallazgos se publicaron en una revista de referencia.', '[{"es":"los hallazgos","ar":"الاكتشافات/النتائج"},{"es":"publicar","ar":"ينشر"},{"es":"la revista científica","ar":"المجلة العلمية"},{"es":"revisar por pares","ar":"مراجعة الأقران"}]'::jsonb, '[{"es":"El estudio fue revisado por pares antes de publicarse.","ar":"رُوجع البحث من الأقران قبل نشره."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('de0a8de2-ba6f-514f-b901-cd7bd1157828', '3fa75bd7-afa3-5408-82f8-67b9439ba410', 'المؤسسات - Las Instituciones', 'هيكل الدولة', 'المؤسسات: el gobierno (الحكومة)، el parlamento (البرلمان)، la constitución (الدستور): El parlamento aprueba las leyes.', '[{"es":"el gobierno","ar":"الحكومة"},{"es":"el parlamento","ar":"البرلمان"},{"es":"la constitución","ar":"الدستور"},{"es":"el ministro","ar":"الوزير"}]'::jsonb, '[{"es":"La constitución garantiza derechos básicos.","ar":"الدستور يكفل حقوقاً أساسية."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, chapter_id, title, description, content, vocabulary, examples, pronunciation, order_num, is_free, xp_reward, duration, createdAt) VALUES
('7a5bba43-95e0-5b02-85b1-29ccab84fd2b', '3fa75bd7-afa3-5408-82f8-67b9439ba410', 'الانتخابات - Las Elecciones', 'عملية التصويت', 'الانتخابات: votar (يصوّت)، el electorado (الناخبون)، la urna (صندوق الاقتراع): La participación electoral fue del setenta por ciento.', '[{"es":"votar","ar":"يصوّت"},{"es":"el electorado","ar":"هيئة الناخبين"},{"es":"la urna","ar":"صندوق الاقتراع"},{"es":"el candidato","ar":"المرشح"}]'::jsonb, '[{"es":"Cada candidato presentó su programa.","ar":"قدم كل مرشح برنامجه."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('5b474723-eb78-5a8c-8499-9765b1118a6e', '3fa75bd7-afa3-5408-82f8-67b9439ba410', 'البرامج السياسية - Programas Políticos', 'ما يعرضه الحزب', 'البرامج: el programa electoral، la promesa electoral (الوعد الانتخابي)， el debate: Los debates televisivos atraen a millones.', '[{"es":"el programa electoral","ar":"البرنامج الانتخابي"},{"es":"la promesa","ar":"الوعد"},{"es":"cumplir una promesa","ar":"يوفّي بوعد"},{"es":"el debate","ar":"المناظرة"}]'::jsonb, '[{"es":"Prometieron bajar los impuestos, pero no lo cumplieron.","ar":"وعدوا بخفض الضرائب ولم يوفوا."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('9999ef18-e730-5f37-a64c-c12e04140321', 'bb74ea07-49d0-58e5-98f6-525dd872dcd0', 'التجارة الدولية - Comercio Internacional', 'تبادل السلع', 'التجارة: la importación y la exportación (الاستيراد والتصدير)， el arancel (الرسوم الجمركية): Los aranceles encarecen los productos importados.', '[{"es":"la importación","ar":"الاستيراد"},{"es":"la exportación","ar":"التصدير"},{"es":"el arancel","ar":"الرسوم الجمركية"},{"es":"el tratado comercial","ar":"الاتفاقية التجارية"}]'::jsonb, '[{"es":"Firmaron un tratado comercial bilateral.","ar":"وقّعا اتفاقية تجارية ثنائية."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('a24dddbb-c09d-5adc-a72b-cff9d2bda2e6', 'bb74ea07-49d0-58e5-98f6-525dd872dcd0', 'الأزمات الاقتصادية - Las Crisis', 'عندما تنهار الأسواق', 'الأزمات: la recesión (الركود)، la inflación (التضخم)، el desempleo (البطالة): La inflación afecta a las familias más humildes.', '[{"es":"la recesión","ar":"الركود"},{"es":"la inflación","ar":"التضخم"},{"es":"el desempleo","ar":"البطالة"},{"es":"la recuperación","ar":"التعافي"}]'::jsonb, '[{"es":"La recuperación económica tardó tres años.","ar":"استغرق التعافي الاقتصادي ثلاث سنوات."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('6f0c9054-64e7-5184-bd10-8b76df1f504e', 'bb74ea07-49d0-58e5-98f6-525dd872dcd0', 'المؤشرات الاقتصادية - Indicadores', 'قياس صحة الاقتصاد', 'المؤشرات: el PIB (الناتج المحلي)، la bolsa (سوق الأسهم)، la cotización (سعر السهم): El PIB creció un dos por ciento.', '[{"es":"el PIB","ar":"الناتج المحلي الإجمالي"},{"es":"la bolsa","ar":"سوق الأسهم"},{"es":"la cotización","ar":"تسعير السهم"},{"es":"el crecimiento","ar":"النمو"}]'::jsonb, '[{"es":"Las acciones subieron en la bolsa de Madrid.","ar":"ارتفعت الأسهم في بورصة مدريد."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('470ba45b-8707-5424-99bb-39c2f7a6bd67', '64f00bcd-8ec1-5ea3-85fd-b04490bab6e2', 'منصات المحتوى - Plataformas de Contenido', 'عالم المحتوى', 'المنصات: la plataforma، el creador de contenido (صانع المحتوى)، la suscripción premium: Los creadores de contenido viven de las suscripciones.', '[{"es":"el creador de contenido","ar":"صانع المحتوى"},{"es":"la suscripción","ar":"الاشتراك"},{"es":"el algoritmo","ar":"الخوارزمية"},{"es":"el viral","ar":"المحتوى الفيروسي"}]'::jsonb, '[{"es":"Su vídeo se hizo viral en horas.","ar":"أصبح فيديوه فيروسياً في ساعات."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('7b90e550-52cb-51cd-ad9a-5bbc9944b9f0', '64f00bcd-8ec1-5ea3-85fd-b04490bab6e2', 'الخوارزميات - Los Algoritmos', 'كيف يقرر النظام', 'الخوارزميات: recomendar contenido (يوصي بمحتوى)، el filtro، la burbuja informativa (فقاعة المعلومة): El algoritmo decide lo que ves primero.', '[{"es":"recomendar","ar":"يوصي بالـ"},{"es":"el filtro","ar":"المرشح"},{"es":"la burbuja informativa","ar":"فقاعة المعلومات"},{"es":"personalizado","ar":"مخصص لك"}]'::jsonb, '[{"es":"Todo mi contenido está personalizado según mis gustos.","ar":"كل محتواي مخصص حسب ذوقي."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('8af58998-3a46-56cf-ac0e-8f466dc93f03', '64f00bcd-8ec1-5ea3-85fd-b04490bab6e2', 'الخصوصية والأمان - Privacidad y Seguridad', 'حماية البيانات', 'الخصوصية: los datos personales (البيانات الشخصية)، la privacidad، la brecha de seguridad (ثغرة أمنية): Protege tus datos personales.', '[{"es":"los datos personales","ar":"البيانات الشخصية"},{"es":"la privacidad","ar":"الخصوصية"},{"es":"la brecha de seguridad","ar":"ثغرة أمنية"},{"es":"el robo de identidad","ar":"سرقة الهوية"}]'::jsonb, '[{"es":"Hubo una brecha de seguridad en la app.","ar":"حدثت ثغرة أمنية في التطبيق."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('ac7921a2-1e29-5a46-8048-289e053f9417', '307f9706-2b15-5d92-9aab-b2b403ee88e4', 'ثيرفانتس ودون كيخوت - Cervantes y el Quijote', 'أب الرواية الحديثة', 'ثيرفانتس: la novela picaresca (الرواية التزمارية)، el idealismo (المثالية): Don Quijote confunde la realidad con los libros de caballerías.', '[{"es":"la novela picaresca","ar":"الرواية التزمارية"},{"es":"el idealismo","ar":"المثالية"},{"es":"la caballería","ar":"الفروسية"},{"es":"la sátira","ar":"الهجاء"}]'::jsonb, '[{"es":"El Quijote es una sátira de los libros de caballerías.","ar":"دون كيخوت هجاء لروايات الفروسية."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('7220ca0a-92f9-5bac-bc20-30a8e37bd07c', '307f9706-2b15-5d92-9aab-b2b403ee88e4', 'لوركا والشعر - Lorca y la Poesía', 'شعر الأندلس الحديث', 'لوركا: la generación del 27 (جيل 27)، el duende (روح الفن الأندلسي): Lorca combinó lo popular y lo vanguardista.', '[{"es":"la generación del 27","ar":"جيل 27 الشعري"},{"es":"el duende","ar":"روح الإلهام الأندلسي"},{"es":"la vanguardia","ar":"الطليعية"},{"es":"el romancero","ar":"الملحمة الغنائية"}]'::jsonb, '[{"es":"El duende de Lorca nace en el cante flamenco.","ar":"روح لوركا تولد في الغناء الفلامنكي."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('28153651-7fbe-58b0-b300-a9180c5155d0', '307f9706-2b15-5d92-9aab-b2b403ee88e4', 'ماتشادو والمشي - Machado y el Camino', 'شاعر الطريق', 'ماتشادو: se hace camino al andar (يصنع الطريق بالمشي): Su poema más famoso habla de la vida como un camino.', '[{"es":"se hace camino al andar","ar":"يصنع الطريق بالمشي"},{"es":"la copla","ar":"المقطوعة الشعبية"},{"es":"el Paisaje","ar":"المشهد الطبيعي"},{"es":"melancólico","ar":"حنين حزين"}]'::jsonb, '[{"es":"Caminante, no hay camino: se hace camino al andar.","ar":"أيها السائر لا طريق: يُصنع الطريق بالمشي."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('7bfd2a7b-150f-533d-93e2-9d125cfdc6fc', '8903a46d-c623-51ce-a127-0e880ac13e79', 'مخرجون عظام - Grandes Directores', 'أعلام السينما اللاتينية', 'المخرجون: Almodóvar في إسبانيا، Cuarón وIñárritu في المكسيك: Las películas de Almodóvar retratan Madrid con colores intensos.', '[{"es":"retratar","ar":"يجسد ويصور"},{"es":"la obra cinematográfica","ar":"العمل السينمائي"},{"es":"el guionista","ar":"كاتب السيناريو"},{"es":"el premiado","ar":"الحائز على جائزة"}]'::jsonb, '[{"es":"Cuarón ganó el Óscar a mejor director.","ar":"فاز كوارون بأوسكار أفضل مخرج."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('722dd6f8-d20a-5919-82d1-6430f853c966', '8903a46d-c623-51ce-a127-0e880ac13e79', 'أفلام لا تُنسى - Películas Inolvidables', 'أعمال مرجعية', 'الأفلام: El laberinto del fauno (متاهة بان)، Roma، Relatos salvajes: Son películas inolvidables por su originalidad.', '[{"es":"inolvidable","ar":"لا يُنسى"},{"es":"la originalidad","ar":"الأصالة"},{"es":"el reparto","ar":"طاقم التمثيل"},{"es":"la banda sonora","ar":"الموسيقى التصويرية"}]'::jsonb, '[{"es":"La banda sonora de esa película es fascinante.","ar":"موسيقى ذلك الفيلم ساحرة."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('dd57c425-9cba-553a-aea6-653e7e9ba547', '8903a46d-c623-51ce-a127-0e880ac13e79', 'الجوائز والمهرجانات - Premios y Festivales', 'تكريم السينما', 'الجوائز: los Goya (جوائز إسبانيا)، el Óscar، el festival de San Sebastián: Los Goya se entregan cada febrero.', '[{"es":"los Goya","ar":"جائزة جويا الإسبانية"},{"es":"la gala","ar":"حفل التكريم"},{"es":"el nominado","ar":"المرشح للجائزة"},{"es":"la entrega de premios","ar":"تسليم الجوائز"}]'::jsonb, '[{"es":"Fue nominado a mejor actor protagonista.","ar":"رُشح لأفضل ممثل رئيسي."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('54730193-84f0-5ea8-b88e-2ff7973ee81b', '70abf35e-f941-52ad-914c-a09d14d89de0', 'إسبانيا وأمريكا - España y América', 'فروق رئيسية', 'الفروق: vosotros (أنتم في إسبانيا) مقابل ustedes، el coche مقابل el carro: En Latinoamérica no se usa vosotros.', '[{"es":"vosotros","ar":"أنتم (إسبانيا فقط)"},{"es":"ustedes","ar":"أنتم (أمريكا والرسمي)"},{"es":"el coche / el carro","ar":"السيارة (إسبانيا/أمريكا)"},{"es":"el ordenador / la computadora","ar":"الحاسوب"}]'::jsonb, '[{"es":"En Argentina dicen «vos» en vez de «tú».","ar":"في الأرجنتين يقولون vos بدل tú."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('c3d9226d-d82b-56c8-96d3-609dcf92f478', '70abf35e-f941-52ad-914c-a09d14d89de0', 'مفردات تختلف - Palabras Distintas', 'كلمة واحدة ومعانٍ متعددة', 'اختلاف المفردات: el zumo/jugo (العصير)، el móvil/celular (الجوال)، el patata/papa (البطاطس): Cuidado, la palabra «coger» significa otra cosa en algunos países.', '[{"es":"el zumo / el jugo","ar":"العصير"},{"es":"el móvil / el celular","ar":"الجوال"},{"es":"la patata / la papa","ar":"البطاطس"},{"es":"el aparcamiento / el parking","ar":"موقف السيارات"}]'::jsonb, '[{"es":"Pide un jugo de naranja en México.","ar":"اطلب jugo برتقال في المكسيك."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('b9bd9531-e6e0-52a9-8a37-f5864c4f7177', '70abf35e-f941-52ad-914c-a09d14d89de0', 'النطق واللهجات - Acentos y Dialectos', 'تنوع النطق', 'النطق: la «s» aspirada في الأندلس، el «ll» que suena como «y» أو «sh» في الأرجنتين: Cada región tiene su acento.', '[{"es":"el acento","ar":"اللكنة"},{"es":"aspirada","ar":"مهموسة"},{"es":"el voseo","ar":"استخدام vos"},{"es":"la entonación","ar":"نغمة الكلام"}]'::jsonb, '[{"es":"El acento andaluz aspira la s final.","ar":"لكنة الأندلس تُهمس السين الأخيرة."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('04719320-efc1-593d-9607-a5282f856199', 'ad08dbb5-47b2-521a-9f56-2c582b22cadc', 'أمثال شائعة - Refranes Populares', 'حكمة شعبية', 'الأمثال: Más vale tarde que nunca (خير أن يتأخر ألا يفعل)، No hay mal que por bien no venga: Usamos refranes en la conversación diaria.', '[{"es":"Más vale tarde que nunca","ar":"خير تأتي متأخراً ألا تأتي"},{"es":"No hay mal que por bien no venga","ar":"ليس شراً إلا وله خير يتبعه"},{"es":"Ojos que no ven...","ar":"ما لم تره العين لا يوجع القلب"},{"es":"el refranero","ar":"مكنون الأمثال"}]'::jsonb, '[{"es":"Llegó tarde, pero más vale tarde que nunca.","ar":"تأخر لكن خير أن يتأخر ألا يفعل."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('9ac0c5e5-83b3-5db4-8e40-b2945f659564', 'ad08dbb5-47b2-521a-9f56-2c582b22cadc', 'تعابير مجازية - Expresiones Figuradas', 'معنى غير حرفي', 'المجاز: estar en las nubes (شارد الذهن)، tirar la casa por la ventana (يبذل بلا حساب): En su boda tiraron la casa por la ventana.', '[{"es":"estar en las nubes","ar":"شارد الذهن"},{"es":"tirar la casa por la ventana","ar":"يبذل بلا حساب"},{"es":"meter la pata","ar":"يرتكب حماقة"},{"es":"dar en el clavo","ar":"يصيب الهدف تماماً"}]'::jsonb, '[{"es":"¡Diste en el clavo con esa idea!","ar":"أصبت الهدف تماماً بفكرتك!"}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('ee1d74f1-ebca-533f-a7f4-c1573f5be4b9', 'ad08dbb5-47b2-521a-9f56-2c582b22cadc', 'متى نستخدم المجاز - Cuándo Usarlas', 'السياق والمقام', 'السياق: التعابير تناسب الحوار غير الرسمي: En una reunión formal, evita demasiadas expresiones coloquiales.', '[{"es":"coloquial","ar":"عامي/ودي"},{"es":"el registro","ar":"مستوى اللغة"},{"es":"formal","ar":"رسمي"},{"es":"el contexto","ar":"السياق"}]'::jsonb, '[{"es":"Ajusta tu registro al contexto de la conversación.","ar":"كيّف مستوى لغتك مع سياق الحديث."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('eda96e23-bc6c-5648-8e89-059aaef85bf5', '0b6f27b8-6f41-5b0f-a40e-567fdbe9333a', 'فن السرد - El Arte de Narrar', 'بناء القصة', 'السرد: el gancho (الخطّاف الافتتاحي)، la tensión narrativa: Un buen relato engancha desde la primera frase.', '[{"es":"el gancho","ar":"جاذب الافتتاح"},{"es":"la tensión narrativa","ar":"التوتر السردي"},{"es":"el giro inesperado","ar":"التقلب غير المتوقع"},{"es":"el narrador omnisciente","ar":"الراوي العليم"}]'::jsonb, '[{"es":"El giro inesperado cambió toda la historia.","ar":"قلب التقلب غير المتوقع كل القصة."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('55cdeda1-22f1-5d85-9cba-b30c755e6e84', '0b6f27b8-6f41-5b0f-a40e-567fdbe9333a', 'وصف الأماكن والأشخاص - Describir', 'صياغة وصفية', 'الوصف: usar los cinco sentidos (استخدم الحواس الخمس): La cocina olía a pan recién hecho y resonaban risas.', '[{"es":"olía a","ar":"كانت تفوح برائحة"},{"es":"resonar","ar":"يتردد صداها"},{"es":"el ambiente","ar":"الأجواء"},{"es":"evocar","ar":"يستحضر ذكرى"}]'::jsonb, '[{"es":"Esa canción evoca mi infancia.","ar":"تلك الأغنية تستحضر طفولتي."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('ed053cec-fd09-5472-a6fe-3c507999c47e', '0b6f27b8-6f41-5b0f-a40e-567fdbe9333a', 'كتابة الحوار - Escribir Diálogos', 'حوار طبيعي', 'الحوار: usar rayas (—) لكل متكلم، giros naturales: —¿Vienes conmigo? —Allá voy.', '[{"es":"la raya de diálogo","ar":"شرطة الحوار"},{"es":"el giro natural","ar":"أسلوب طبيعي"},{"es":"la muletilla","ar":"كلمة الحشو"},{"es":"entrelazar","ar":"يترابط"}]'::jsonb, '[{"es":"Los diálogos deben fluir sin muletillas repetidas.","ar":"يجب أن يتدفق الحوار دون حشو متكرر."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('b4f6d78e-8551-54d3-b239-e817150bdf2f', '98fcf487-4c24-5259-bbaf-e608716cfaf8', 'معادلات الترجمة - Equivalencias', 'لا ترجمة حرفية دائماً', 'المعادلات: tomar el pelo ≠ آخذ الشعر (هو يمزح)، hacer la vista gorda (يتغاضى): Traducir es buscar el sentido, no las palabras.', '[{"es":"hacer la vista gorda","ar":"يتغاضى متعمداً"},{"es":"el sentido","ar":"المعنى المقصود"},{"es":"la equivalencia","ar":"المعادل"},{"es":"literal","ar":"حرفي"}]'::jsonb, '[{"es":"La traducción literal a veces no tiene sentido.","ar":"الترجمة الحرفية أحياناً بلا معنى."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('02404625-f1d9-5c56-a37a-151eb36d1f95', '98fcf487-4c24-5259-bbaf-e608716cfaf8', 'محاذير الترجمة - Falsos Amigos', 'كلمات تخدع', 'المحاذير: «actualmente» تعني حالياً لا فعلياً، «embarazada» تعني حاملاً: ¡Cuidado con los falsos amigos!', '[{"es":"los falsos amigos","ar":"الأصدقاء المزيفون لغوياً"},{"es":"actualmente","ar":"حالياً (لا فعلياً)"},{"es":"embarazada","ar":"حامل (لا محرجة)"},{"es":"la trampa","ar":"الفخ"}]'::jsonb, '[{"es":"«Éxito» significa éxito, no salida.","ar":"éxito يعني نجاحاً لا خروجاً."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('36b72acc-3638-5e67-8782-b25c85c1e2a0', '98fcf487-4c24-5259-bbaf-e608716cfaf8', 'مراجعة الترجمة - Revisar la Traducción', 'تصحيح وإتقان', 'المراجعة: revisar el tono، ajustar la puntuación: Reviso siempre dos veces antes de entregar.', '[{"es":"revisar","ar":"يراجع"},{"es":"el tono","ar":"النبرة"},{"es":"ajustar","ar":"يضبط"},{"es":"entregar","ar":"يسلّم العمل"}]'::jsonb, '[{"es":"Ajusté el tono para el público árabe.","ar":"ضبطت النبرة للجمهور العربي."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('7a4db6c6-b36e-5a6d-9da2-45f0f31bed77', '9808c5bb-5746-593e-9c77-a5be85dbdef3', 'أدوار المناظرة - Roles del Debate', 'توزيع الأدوار', 'الأدوار: el moderador (المنسق)، el ponente (المتكلم)، el turno de palabra (دور الكلام): El moderador reparte los turnos de palabra.', '[{"es":"el moderador","ar":"منسق المناظرة"},{"es":"el ponente","ar":"المتكلم الرسمي"},{"es":"el turno de palabra","ar":"دور الكلام"},{"es":"la intervención","ar":"المداخلة"}]'::jsonb, '[{"es":"Tiene la palabra la representante del equipo contrario.","ar":"للمتكلمة عن الفريق المنافس الكلمة."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('c3ac03f4-a229-578e-b7ab-beb337d225ec', '9808c5bb-5746-593e-9c77-a5be85dbdef3', 'الحجج المضادة - Refutar con Elegancia', 'الرد الراقي', 'الرد: respetuosamente (بأدب)، sin descalificar (دون تحقير): Refuto tu argumento, no a ti como persona.', '[{"es":"descalificar","ar":"يحقّر شخصاً"},{"es":"con datos en la mano","ar":"وبين يديك بيانات"},{"es":"la falacia","ar":"الحجة الفاسدة"},{"es":"rectificar","ar":"يصحح موقفه"}]'::jsonb, '[{"es":"Reconozco mi error y rectifico.","ar":"أعترف بخطئي وأصححه."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('3eb14eca-86fe-5259-96bd-b003f4e3c852', '9808c5bb-5746-593e-9c77-a5be85dbdef3', 'خاتمة مقنعة - Cerrar con Fuerza', 'الخاتمة الحاسمة', 'الخاتمة: en definitiva (خلاصة القول)، queda demostrado que (أثبتنا أن): En definitiva, los hechos hablan por sí solos.', '[{"es":"en definitiva","ar":"خلاصة القول"},{"es":"queda demostrado","ar":"قد ثبت"},{"es":"los hechos","ar":"الوقائع"},{"es":"la postura final","ar":"الموقف الأخير"}]'::jsonb, '[{"es":"Queda demostrado que nuestra postura es sólida.","ar":"قد ثبت أن موقفنا راسخ."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('082a5050-ad66-52bf-803e-8a949f872b04', 'b4ee7526-3121-51bd-ab6e-687406f8cf83', 'عرض الفكرة - Presentar un Pitch', 'عرض قصير مؤثر', 'العرض: el elevator pitch (عرض المصعد)، el gancho inicial: Un pitch debe durar menos de dos minutos.', '[{"es":"el elevator pitch","ar":"عرض المصعد القصير"},{"es":"el gancho inicial","ar":"الافتتاحية الجاذبة"},{"es":"captar la atención","ar":"يستولي على الانتباه"},{"es":"la propuesta de valor","ar":"قيمة العرض"}]'::jsonb, '[{"es":"Nuestra propuesta de valor es única en el mercado.","ar":"قيمة عرضنا فريدة في السوق."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('f24d992d-2d79-5585-b4fd-fbff4fe2ca07', 'b4ee7526-3121-51bd-ab6e-687406f8cf83', 'الإقناع بالبيانات - Persuadir con Datos', 'أرقام تتكلم', 'البيانات: respaldar con cifras (يدعم بالأرقام)، el crecimiento proyectado (النمو المتوقع): Las cifras respaldan nuestro plan de expansión.', '[{"es":"respaldar","ar":"يدعم بالدليل"},{"es":"las cifras","ar":"الأرقام"},{"es":"proyectado","ar":"متوقع مستقبلاً"},{"es":"la expansión","ar":"التوسع"}]'::jsonb, '[{"es":"Proyectamos un crecimiento del treinta por ciento.","ar":"نتوقع نمواً بنسبة ثلاثين بالمئة."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('98bde77a-65f5-5158-a003-7e6ffbe4cfd2', 'b4ee7526-3121-51bd-ab6e-687406f8cf83', 'الإلقاء الواثق - Hablar con Seguridad', 'حضور قوي', 'الإلقاء: mantener el contacto visual (يحافظ على التواصل البصري)، el ritmo pausado (الإيقاع الهادئ): Habla con ritmo pausado y claridad.', '[{"es":"el contacto visual","ar":"التواصل البصري"},{"es":"pausado","ar":"هادئ الإيقاع"},{"es":"la muletilla","ar":"كلمة الحشو"},{"es":"la seguridad","ar":"الثقة"}]'::jsonb, '[{"es":"Evita las muletillas como «eh» y «o sea».","ar":"تجنب الحشو مثل eh وo sea."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('fc553908-9853-5eef-9168-6197bad3fd49', 'fd0f9af4-a52d-510d-bcde-3e0b63bded32', 'أسئلة المواقف - Preguntas Situacionales', 'ماذا لو...؟', 'المواقف: ¿Cómo resolvería un conflicto entre compañeros? (كيف تحل خلافاً بين زملاء؟): Yo primero escucharía a ambas partes.', '[{"es":"situacional","ar":"موقف افتراضي"},{"es":"resolvería","ar":"سأحل (شرطي مهذب)"},{"es":"ambas partes","ar":"الطرفان معاً"},{"es":"la mediación","ar":"الوساطة"}]'::jsonb, '[{"es":"Primero escucharía a ambas partes con calma.","ar":"أولاً سأستمع للطرفين بهدوء."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('63ed14a9-b728-578e-8baf-0cc549bf6924', 'fd0f9af4-a52d-510d-bcde-3e0b63bded32', 'سرد الإنجازات - Contar Logros', 'طريقة STAR', 'الإنجاز: describir la situación، la acción tomada، el resultado: Mi liderazgo redujo los plazos un veinte por ciento.', '[{"es":"el logro","ar":"الإنجاز"},{"es":"la acción tomada","ar":"الإجراء المتخذ"},{"es":"el resultado medible","ar":"نتيجة قابلة للقياس"},{"es":"destacar","ar":"يبرز أهمية"}]'::jsonb, '[{"es":"El resultado fue medible y positivo.","ar":"كانت النتيجة قابلة للقياس وإيجابية."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('48ee11fb-f6b7-5d6d-b137-4afdd9b6dfff', 'fd0f9af4-a52d-510d-bcde-3e0b63bded32', 'تفاوض الراتب - Negociar el Salario', 'موقف مالي حاسم', 'الراتب: el salario bruto (قبل الضريبة)، las expectativas salariales، las ventajas en especie: Además del salario, valoro la flexibilidad horaria.', '[{"es":"el salario bruto","ar":"الراتب الإجمالي"},{"es":"las expectativas salariales","ar":"توقعات الراتب"},{"es":"las ventajas en especie","ar":"مزايا عينية"},{"es":"la revisión anual","ar":"المراجعة السنوية"}]'::jsonb, '[{"es":"¿Incluye este sueldo las ventajas en especie?","ar":"هل يشمل هذا الراتب المزايا العينية؟"}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('707172d0-d5bd-590b-9259-d94dd0009c1f', '5af6f26e-8b60-599a-8456-503735de82d4', 'بريد عمل فعّال - Correos Eficaces', 'واضح ومختصر', 'الفعالية: asunto claro (موضوع واضح)، una idea por párrafo (فكرة لكل فقرة): Te escribo para confirmar la reunión del jueves.', '[{"es":"eficaz","ar":"فعّال"},{"es":"confirmar la reunión","ar":"يؤكد الاجتماع"},{"es":"en respuesta a","ar":"رداً على"},{"es":"quedo a la espera","ar":"بانتظار ردك"}]'::jsonb, '[{"es":"En respuesta a tu correo, adjunto los datos.","ar":"رداً على بريدك، أرفق البيانات."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('f5dd72cd-1f31-5b8b-bbb3-1cf8634fd2fe', '5af6f26e-8b60-599a-8456-503735de82d4', 'التقرير المختصر - El Informe Breve', 'خلاصة تنفيذية', 'التقرير: el resumen ejecutivo (الخلاصة التنفيذية)، las conclusiones clave (الاستنتاجات الرئيسية): El informe consta de tres páginas y un anexo.', '[{"es":"el resumen ejecutivo","ar":"الخلاصة التنفيذية"},{"es":"las conclusiones clave","ar":"الاستنتاجات الرئيسية"},{"es":"el anexo","ar":"الملحق"},{"es":"constar de","ar":"يتكون من"}]'::jsonb, '[{"es":"El anexo contiene las tablas detalladas.","ar":"الملحق يحتوي الجداول التفصيلية."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('78a5dc07-8095-5138-9e54-00068f85bca1', '5af6f26e-8b60-599a-8456-503735de82d4', 'المتابعة - Hacer Seguimiento', 'طيّب الخاطر ودفع الملف', 'المتابعة: hacer seguimiento (يتابع)، ¿Hay alguna novedad? (هل من جديد؟): Le escribo para hacer seguimiento a nuestra propuesta.', '[{"es":"hacer seguimiento","ar":"يتابع موضوعاً"},{"es":"la novedad","ar":"جديد المستجدات"},{"es":"dar prisa amable","ar":"تذكير لبق"},{"es":"el plazo vence","ar":"تنتهي المهلة"}]'::jsonb, '[{"es":"El plazo vence el viernes, ¿podemos avanzar?","ar":"تنتهي المهلة الجمعة، هل نتقدم؟"}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('60b232e6-d380-5ca1-8d22-b926f13bd06e', 'd4790b18-50bb-55f1-a1b8-b2311b437d05', 'بنية التقرير - Estructura del Informe', 'من الغلاف للخلاصة', 'البنية: la portada (الغلاف)، la metodología، los hallazgos， las recomendaciones: Las recomendaciones van al final del informe.', '[{"es":"la portada","ar":"صفحة الغلاف"},{"es":"las recomendaciones","ar":"التوصيات"},{"es":"el índice","ar":"الفهرس"},{"es":"la paginación","ar":"ترقيم الصفحات"}]'::jsonb, '[{"es":"El informe incluye recomendaciones prácticas.","ar":"التقرير يتضمن توصيات عملية."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('7a47037a-b2b4-5290-8191-0b7b85e0b97d', 'd4790b18-50bb-55f1-a1b8-b2311b437d05', 'لغة موضوعية - Redacción Impersonal', 'حيد الذات', 'الموضوعية: se recomienda (يوصى بـ)، se observa، se concluye: Se recomienda ampliar la muestra del estudio.', '[{"es":"se recomienda","ar":"يوصى بـ"},{"es":"se concluye","ar":"يُستنتج"},{"es":"impersonal","ar":"غير شخصي"},{"es":"la objetividad","ar":"الموضوعية"}]'::jsonb, '[{"es":"Se concluye que el plan es viable.","ar":"يُستنتج أن الخطة قابلة للتنفيذ."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, chapter_id, title, description, content, vocabulary, examples, pronunciation, order_num, is_free, xp_reward, duration, createdAt) VALUES
('a8d760b5-28c6-560e-83ea-0aca466fca67', 'd4790b18-50bb-55f1-a1b8-b2311b437d05', 'الأرقام والجداول - Cifras y Tablas', 'عرض البيانات', 'الأرقام: la tabla (الجدول)، el porcentaje، la tendencia (الاتجاه): La tabla muestra una tendencia al alza.', '[{"es":"la tabla","ar":"الجدول البياني"},{"es":"el porcentaje","ar":"النسبة المئوية"},{"es":"la tendencia","ar":"الاتجاه العام"},{"es":"al alza","ar":"صعوداً"}]'::jsonb, '[{"es":"Las ventas muestran una tendencia al alza.","ar":"تُظهر المبيعات اتجاهاً صعودياً."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('877483ae-0ece-57af-a208-9153746a07e6', '2226eab2-46ca-57cd-ba1a-2c29083f67d2', 'أخطاء مزمنة - Errores Típicos', 'توقف عن تكرارها', 'الأخطاء: «soy de acuerdo» ❌ (الصحيح: estoy de acuerdo)، «tengo 20 años» ✓ لا «soy 20»: Repasa estos errores hasta automatizarlos.', '[{"es":"típico","ar":"معتاد/مزمن"},{"es":"automatizar","ar":"يؤتمت في عقلك"},{"es":"el hábito","ar":"العادة اللغوية"},{"es":"corregir","ar":"يصحح"}]'::jsonb, '[{"es":"Corrígeme siempre que me equivoque.","ar":"صحح لي كلما أخطأت."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('23fa40fd-08b0-5f02-92cb-561ad579bd83', '2226eab2-46ca-57cd-ba1a-2c29083f67d2', 'فروق الأزمنة - Matices de Tiempos', 'متى تستخدم كل زمن', 'الأزمنة: he comido (اليوم)، comí (أمس)، comía (عادة)، había comido (قبل حدث ماضٍ): Elige el tiempo según el marco temporal.', '[{"es":"el marco temporal","ar":"الإطار الزمني"},{"es":"el matiz","ar":"الفرق الدقيق"},{"es":"expresar","ar":"يعبّر عن"},{"es":"la secuencia","ar":"التسلسل"}]'::jsonb, '[{"es":"Hoy he comido tarde; ayer comí temprano.","ar":"اليوم أكلت متأخراً؛ وأمس مبكراً."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('f4665c63-45d2-5769-a894-a268e983cae9', '2226eab2-46ca-57cd-ba1a-2c29083f67d2', 'حزم القواعد - Consolidar', 'ترسيخ ما تعلمته', 'الترسيخ: consolidar (يرسّخ)، la práctica deliberada (تدريب مقصود): La práctica deliberada consolida las estructuras.', '[{"es":"consolidar","ar":"يرسّخ"},{"es":"la estructura","ar":"البنية النحوية"},{"es":"la fluidez","ar":"الطلاقة"},{"es":"retener","ar":"يحفظ في الذاكرة"}]'::jsonb, '[{"es":"Repite las estructuras hasta retenerlas.","ar":"كرر البنى حتى ترسخ في ذاكرتك."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('254cdf56-bbda-5fda-a0fd-4efb07f1eb74', '5b4789ea-2be9-5345-920e-4bb7f89503f5', 'أقسام الامتحان - Partes del Examen', 'ماذا يختبر DELE', 'الأقسام: comprensión lectora y auditiva، expresión escrita y oral: El DELE B2 consta de cuatro pruebas.', '[{"es":"la prueba","ar":"قسم الامتحان"},{"es":"la comprensión lectora","ar":"قسم القراءة"},{"es":"la expresión oral","ar":"التعبير الشفوي"},{"es":"la convocatoria","ar":"دورة الامتحان"}]'::jsonb, '[{"es":"Me presento a la convocatoria de noviembre.","ar":"أتقدم في دورة نوفمبر."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('6e528427-6f70-5642-b925-3907bc939800', '5b4789ea-2be9-5345-920e-4bb7f89503f5', 'استراتيجيات الحل - Estrategias', 'إدارة الوقت والخيارات', 'الاستراتيجيات: administrar el tiempo (يدير وقته)، descartar opciones (يستبعد الخيارات): Lee las preguntas antes que el texto.', '[{"es":"administrar el tiempo","ar":"يدير وقته"},{"es":"descartar","ar":"يستبعد"},{"es":"la pista","ar":"الدليل في النص"},{"es":"subrayar","ar":"يسطّر"}]'::jsonb, '[{"es":"Subraya las palabras clave del texto.","ar":"سطّر الكلمات المفتاحية في النص."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('d2958f9e-bacc-543a-9f21-40fad1f927fc', '5b4789ea-2be9-5345-920e-4bb7f89503f5', 'يوم الامتحان - El Día del Examen', 'نصائح الأداء', 'يوم الامتحان: llegar con antelación (يصل مبكراً)، leer las instrucciones con calma: Duerme bien la noche anterior.', '[{"es":"con antelación","ar":"قبل الوقت بكفاية"},{"es":"las instrucciones","ar":"التعليمات"},{"es":"con calma","ar":"بهدوء"},{"es":"el diploma DELE","ar":"شهادة ديبل"}]'::jsonb, '[{"es":"Leer las instrucciones con calma evita errores.","ar":"قراءة التعليمات بهدوء تمنع الأخطاء."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()),
('fa9a9cf3-1a3f-59bd-b74b-d83f5fcdcf6b', '0c844a80-661b-501e-8594-2b9ca10d96b1', 'المسرح الإسباني - El Teatro Español', 'نصوص وعروض مسرحية', 'المسرح: la función (العرض)، el telón (الستارة)، el ensayo (البروفة)، el aplauso (التصفيق): El telón se levantó a las diez en punto.', '[{"es":"la función","ar":"عرض مسرحي"},{"es":"el telón","ar":"ستارة المسرح"},{"es":"el ensayo","ar":"البروفة"},{"es":"el aplauso","ar":"التصفيق"}]'::jsonb, '[{"es":"La función se agotó en dos días.","ar":"نفدت تذاكر العرض في يومين."}]'::jsonb, '[]'::jsonb, 1, TRUE, 30, 15, now()),
('5430036b-91c0-5cf6-ad7c-9032b5f367e4', '0c844a80-661b-501e-8594-2b9ca10d96b1', 'فن الخطابة - La Oratoria', 'خطبة مؤثرة', 'الخطابة: el discurso (الخطبة)، la tribuna (المنصة)، la pausa dramática (التوقف المؤثر): Un buen discurso empieza con una historia.', '[{"es":"el discurso","ar":"الخطبة"},{"es":"la tribuna","ar":"منصة الخطابة"},{"es":"la pausa dramática","ar":"توقف مؤثر"},{"es":"convencer","ar":"يُقنع"}]'::jsonb, '[{"es":"Su discurso convenció a todo el auditorio.","ar":"أقنعت خطبته الجمهور كله."}]'::jsonb, '[]'::jsonb, 2, TRUE, 30, 15, now()),
('44886b46-416e-5c3a-a4d9-d3a63911c5a6', '0c844a80-661b-501e-8594-2b9ca10d96b1', 'الارتجال - Improvisar', 'التحدث دون تحضير', 'الارتجال: improvisar (يرتجل)، sobre la marcha (في الحال)، apañárselas (يتصرف بمفرده): Improvisé la respuesta sobre la marcha.', '[{"es":"improvisar","ar":"يرتجل"},{"es":"sobre la marcha","ar":"في الحال"},{"es":"apañárselas","ar":"يتدبر أموره"},{"es":"la pregunta difícil","ar":"السؤال العسير"}]'::jsonb, '[{"es":"Con práctica, aprendes a apañarte en cualquier situación.","ar":"مع التدريب تتعلم التصرف في أي موقف."}]'::jsonb, '[]'::jsonb, 3, TRUE, 30, 15, now()) ON CONFLICT DO NOTHING;
INSERT INTO quizzes (id, lesson_id, question, type, options, correct_answer, explanation, order_num) VALUES
(5544fd62-8019-5072-936e-78ebe0e29d7e, '0ea6b0de-e1ec-57e3-b044-353e91909f84', 'أي كلمة مؤنثة رغم انتهائها بحرف o؟', 'multiple_choice', '["el libro","la mano","el día","el mapa"]'::jsonb, 'la mano', 'la mano استثناء: مؤنثة رغم انتهائها بـ o، ودليلها أداة التعريف la.', 1),
(3ed70cba-a9c6-51f7-b857-6eb5d702c4ef, '0a1e855d-291d-5771-9404-41b08c7e0487', 'جمع كلمة ciudad هو:', 'multiple_choice', '["ciudads","ciudaded","cityes","ciudades"]'::jsonb, 'ciudades', 'الاسم المنتهي بحرف ساكن يأخذ es في الجمع: ciudad → ciudades.', 1),
(36814fc8-01c0-5102-952f-c66dc9584a95, '3aacaf2a-5ca8-55c3-932d-87f8c85b656b', 'أكمل: ___ hermanos son mayores (إخوتي):', 'multiple_choice', '["Mis","Mi","Su","Tus"]'::jsonb, 'Mis', 'hermanos جمع، فتكون صفة الملكية mis وليس mi.', 1),
(a8315be1-1591-534c-a3af-4f01c064af2f, '870a54bc-7a7c-5717-bc7b-df85e7ccb231', 'للإشارة إلى شيء بعيد عن المتحدث والمخاطب معاً:', 'multiple_choice', '["este","ese","aquel","mi"]'::jsonb, 'aquel', 'aquel للبعيد عن الطرفين، وese للمتوسط، وeste للقريب من المتحدث.', 1),
(45fa2efd-c4d9-5915-a126-85cc64a4acc8, '58992978-2134-5c83-bf75-685605cd6e09', 'أكمل: el ___ piso (الثالث):', 'multiple_choice', '["tres","tercero","tercera","trece"]'::jsonb, 'tercero', 'العدد الترتيبي tercero يفقد الـ o قبل الاسم المذكر: el tercer piso أو el tercero.', 1),
(fa33ff69-3062-5df6-83cb-2b6114698c7c, '85142f00-96c1-5201-bccd-64f5f91c8b21', 'تصريف vivir مع nosotros:', 'multiple_choice', '["vivemos","vivimos","viváis","viven"]'::jsonb, 'vivimos', 'أفعال مجموعة -ir تأخذ نهاية imos مع nosotros: vivir → vivimos.', 1),
(ab1b469f-658b-58d9-940e-a433b2777f9b, '860cd1f7-680c-5a40-9ddf-66fe2f10e4ef', 'تصريف beber مع yo:', 'multiple_choice', '["bebo","bebes","bebe","beben"]'::jsonb, 'bebo', 'أفعال مجموعة -er تأخذ نهاية o مع yo: beber → bebo.', 1),
(d43488cf-7952-5e30-82c9-9be59bce1409, '077507be-09bd-5d5d-aaa5-23362045c54c', 'تصريف hacer مع yo:', 'multiple_choice', '["haco","hago","haces","hacer"]'::jsonb, 'hago', 'hago فعل شاذ في المضارع: لا يتبع نهايات -er المنتظمة مع yo.', 1),
(3462805a-4c7c-5bc7-9911-f454d834d105, '80782318-150c-5c24-bde7-ccbf0163746e', '«لا أرى أحداً» بالإسبانية:', 'multiple_choice', '["No veo nadie","No veo nada","No nadie veo","Veo no nadie"]'::jsonb, 'No veo nadie', 'nadie للمألوس (لا أحد)، وnada لغير العاقل (لا شيء): No veo a nadie.', 1),
(7933b5f3-7d5e-50d0-847e-a77350833dbe, '16dd5d4e-5d49-5370-8d57-aaf22239848e', 'للسؤال عن المكان نستخدم:', 'multiple_choice', '["¿Quién?","¿Dónde?","¿Cuándo?","¿Qué?"]'::jsonb, '¿Dónde?', '¿Dónde? أداة الاستفهام عن المكان.', 1),
(e3253939-39b6-5a31-9c9b-89e3f38f6682, 'd4e22a54-2a4d-5542-9929-e1266acb2dca', '«توجد مشكلة» بالإسبانية:', 'multiple_choice', '["Hay un problema","Es un problema","Está un problema","Hay el problema"]'::jsonb, 'Hay un problema', 'hay تعبّر عن الوجود ويأتي بعدها نكرة: Hay un problema.', 1),
(f5d3132f-e7ec-59cb-a628-027265441e6c, '988f4dbc-bdd4-56c2-acf4-109b41f807dd', 'a + el =', 'multiple_choice', '["el","al","del","a el"]'::jsonb, 'al', 'الاختصار الوحيد مع a + el هو al، ولا يجوز فصلهما.', 1),
(3855da6e-8fa2-5188-8010-032a5053283f, 'a853fb85-fc8d-5068-8bb1-9b4be0993f86', '«قهوة بدون سكر» بالإسبانية:', 'multiple_choice', '["café sin azúcar","café con azúcar","café de azúcar","café en azúcar"]'::jsonb, 'café sin azúcar', 'sin تعني «بدون»، أما con فتعني «مع».', 1),
(185832ee-9f76-5ea4-bd12-c5faad49224e, 'd69efb28-2323-59b3-9f6c-b75759b249ea', '«أحياناً» بالإسبانية:', 'multiple_choice', '["siempre","a veces","nunca","a menudo"]'::jsonb, 'a veces', 'a veces تعني أحياناً، وsiempre دائماً، وnunca أبداً.', 1),
(a8726201-4068-5891-8fe7-95a18c46d731, '6778249e-94bf-59af-847d-623e11dc6c4a', '«أنا أدرس الآن» بالإسبانية:', 'multiple_choice', '["Estoy estudiar","Estoy estudiando","Estudiando estoy","Estoy estudio"]'::jsonb, 'Estoy estudiando', 'estar بمعناه المصرّف + gerundio: estoy + estudiando.', 1),
(52766e51-1f76-5df8-9810-30c112b8418f, 'd32551e4-6fca-542b-93d1-f2d3f975685e', 'yo + hablar في الماضي القريب:', 'multiple_choice', '["he hablado","he hablar","hablo he","había hablado"]'::jsonb, 'he hablado', 'he (فعل haber مع yo) + التصريف الثالث hablado.', 1),
(830c630d-dc65-561d-8c9f-cf9ad39d042e, '600e647a-b4f6-57c9-875c-7d8f41b1fabf', '«سنرحل غداً» بالإسبانية:', 'multiple_choice', '["Vamos a viajar mañana","Vamos viajar mañana","Viajamos a mañana","Ir a viajamos mañana"]'::jsonb, 'Vamos a viajar mañana', 'vamos + a + المصدر viajar = المستقبل القريب.', 1),
(e224c26a-512c-5336-8a40-8dedb12b3706, '3490a8e3-a85a-587d-9c28-26eaadb9cdf7', 'أمر من hablar للمخاطب المفرد (tú):', 'multiple_choice', '["¡Hablas!","¡Hables!","¡Habla!","¡Hablar!"]'::jsonb, '¡Habla!', 'أمر tú الإثباتي يأخذ صيغة المضارع للغائب: habla.', 1),
(f4f33b91-abe3-5c53-9fa2-5e07135a2445, '573fb1e3-4ea9-526c-a97b-b71921b9e6ba', '«يجب أن أعمل» بالإسبانية:', 'multiple_choice', '["Tengo trabajar","Tengo que trabajar","Debo a trabajar","Trabajo que tengo"]'::jsonb, 'Tengo que trabajar', 'tener que + مصدر تعني «يجب أن».', 1),
(65281fdc-f5fd-526a-a155-817720b48633, '584e0abc-0738-5508-9166-2a2e09fa7f1b', '«أشعر بالملل الآن» بالإسبانية:', 'multiple_choice', '["Estoy aburrido","Soy aburrido","Estoy aburrimiento","Soy aburrimiento"]'::jsonb, 'Estoy aburrido', 'الملل شعور مؤقت فنستخدم estar: estoy aburrido.', 1),
(fdd7e610-ac12-5a46-8599-8c03854fedc4, '19f51bc3-9b4b-5384-b04f-cc38b047fc82', '«هذه الهدية لك» بالإسبانية:', 'multiple_choice', '["por ti","para ti","a ti","con ti"]'::jsonb, 'para ti', 'عند تحديد المستفيد/المقابل نستخدم para.', 1),
(a60e7e45-f818-581f-87f6-43499291ffcd, 'a76028ec-130e-5ccb-ac15-a18d54268d00', '«أعرف صديقك (شخصاً)» بالإسبانية:', 'multiple_choice', '["Sé a tu amigo","Sé tu amigo","Conozco tu saber","Conozco a tu amigo"]'::jsonb, 'Conozco a tu amigo', 'معرفة الأشخاص تأخذ conocer + a الشخص: Conozco a tu amigo.', 1),
(83cfad24-acd0-5d90-b845-fe6a2e0e0740, '130e14e8-6ae5-5b2a-89d6-114c270f4e3f', '«أراه (الكتاب)» بالإسبانية:', 'multiple_choice', '["Le veo","Lo veo","Veo lo","La veo"]'::jsonb, 'Lo veo', 'الكتاب مذكر فضميره lo، ويوضع قبل الفعل المصرّف.', 1),
(5f66a0d1-1de2-5dc4-bb90-f753fc915990, '3f5e3f64-dc1c-5630-acf7-540791fb2728', '«أحمد أطول من كريم» بالإسبانية:', 'multiple_choice', '["Ahmed es más alto que Karim","Ahmed es más alto como Karim","Ahmed es tan alto que Karim","Ahmed es alto más que Karim"]'::jsonb, 'Ahmed es más alto que Karim', 'المقارنة: más + الصفة + que.', 1),
(fa29c16d-fe0f-53ca-9820-793679e85e26, '6b925589-2a49-55f9-8c79-f273dae48da4', '«كنت قد انتهيت» بالإسبانية:', 'multiple_choice', '["había terminado","hube terminado","había terminar","había terminando"]'::jsonb, 'había terminado', 'había + التصريف الثالث terminado = الماضي الأسبق.', 1),
(c16595b6-856c-57db-85ef-829d726dfbfa, 'f793a8af-12dc-5953-ad6f-11e8131589fe', '«سأكون قد وصلت» بالإسبانية:', 'multiple_choice', '["haber llegado","habré llegado","habría llegado","habré llegando"]'::jsonb, 'habré llegado', 'habré (فعل haber في المستقبل) + التصريف الثالث llegado.', 1),
(3af76204-bf9b-5f7a-af48-4035066e2995, '0d39b537-955e-5e78-b758-38706b47c6e7', 'yo + hablar في الشرط المركب:', 'multiple_choice', '["habría hablado","habré hablado","había hablado","habría hablar"]'::jsonb, 'habría hablado', 'habría + التصريف الثالث: habría hablado.', 1),
(f30765ff-53b0-5812-9ec9-49bfafedd716, 'eca2731a-afc8-541c-a45b-02637e1f870d', 'si + yo + tener في الشرط غير الواقعي:', 'multiple_choice', '["tengo","tendré","tuviera","tendría"]'::jsonb, 'tuviera', 'الشرط الثاني يأخذ imperfecto de subjuntivo: tuviera.', 1),
(60769dd4-f7ee-528f-a799-2c1b04fb1e23, '13af96b9-44bb-58c4-9d4d-97d6661e7858', 'النوع الأول من الجمل الشرطية يتركب من:', 'multiple_choice', '["Si + مضارع، مستقبل","Si + ماضٍ، مضارع","Si + مصدر، أمر","Si + مستقبل، ماضٍ"]'::jsonb, 'Si + مضارع، مستقبل', 'الشرط القابل للتحقق: Si + presente، والنتيجة futuro simple.', 1),
(ef98b2e7-3c8b-5ebe-a27c-895cd19caaac, '0a1420c8-bebe-5559-9802-6524d7c109a5', 'نقل جملة «Estoy cansado» على لسان متكلم في الماضي:', 'multiple_choice', '["Dijo que estoy cansado","Dijo que estaba cansado","Dijo que estar cansado","Digo que estaba cansado"]'::jsonb, 'Dijo que estaba cansado', 'الزمن يتراجع في الكلام غير المباشر: estoy → estaba.', 1),
(bcb89f7a-3eb7-5c8b-903b-b4bce4c1e44c, '07cb5415-c020-5500-b8df-98459351ed62', 'أكمل: la ciudad ___ vivo:', 'multiple_choice', '["que","quien","donde","cual"]'::jsonb, 'donde', 'للمكان نستخدم الموصول donde.', 1),
(d297a824-5114-503d-9d64-c43f6c40c990, '5c0b7dbd-cf28-5dfa-9d64-74a44c9f7edd', 'المبني للمجهول يُكوَّن بـ:', 'multiple_choice', '["estar + participio","ser + participio","haber + participio","ir + participio"]'::jsonb, 'ser + participio', 'المجهول الكلاسيكي: ser + التصريف الثالث + por.', 1),
(c38b609f-8d15-55a1-bd8f-76acfec5da2a, 'f47810c5-fd5e-5fb9-8d4b-79f426b9c490', '«وصل للتوّ» بالإسبانية:', 'multiple_choice', '["acaba de llegar","acaba llegando","acaba a llegar","acaba llegado"]'::jsonb, 'acaba de llegar', 'acabar de + مصدر تعني «للتوّ فعل شيئاً».', 1),
(f2b8adff-4873-5557-bd6c-ef3a2b534c3e, 'fd161c35-e589-534c-aa7a-c28d26c2da93', 'أكمل: las flores ___ (blanco):', 'multiple_choice', '["blanco","blanca","blancos","blancas"]'::jsonb, 'blancas', 'flores جمع مؤنث، فالصفة تأخذ جمع المؤنث blancas.', 1),
(04b43cc1-031b-598b-b847-d221282052dc, '2f7eba50-f23d-5ef6-94c2-d03e2af05d5e', 'الفرق بين sí و si:', 'multiple_choice', '["كلاهما بمعنى نعم","sí = إذا و si = نعم","كلاهما بمعنى إذا","sí = نعم و si = إذا"]'::jsonb, 'sí = نعم و si = إذا', 'علامة النبر على sí تميّزها: sí نعم، وsi إذا شرطية.', 1),
(302f02f6-52bc-5e6c-b29a-89535050e4ab, '5b70d643-1a47-50ff-9b94-3bb9544be93d', 'العبارة الصحيحة:', 'multiple_choice', '["Soy de acuerdo","Estoy de acuerdo","Estoy acuerdo","Soy acuerdo"]'::jsonb, 'Estoy de acuerdo', 'de acuerdo حالة مؤقتة فتأخذ estar: Estoy de acuerdo.', 1),
(6712f5d3-013c-5d71-a789-1cb9446d4c45, '9338211f-33ca-546a-b3a9-d5019a929714', 'الختام المعتاد للرسالة الرسمية:', 'multiple_choice', '["Saludos cordial","Cordiales saludo","Muchas saludes","Saludos cordiales"]'::jsonb, 'Saludos cordiales', 'الصيغة الثابتة للختام الرسمي: Saludos cordiales.', 1),
(2098d2fd-b7de-5ef8-b985-81ae76527112, 'b7fa2b2f-6bd7-5175-8932-a8a413476abc', '«الفكرة الرئيسة» بالإسبانية:', 'multiple_choice', '["la idea principale","el idea principal","la idea principal","la idea principada"]'::jsonb, 'la idea principal', 'idea مؤنث فتأخذ la، وprincipal صفة لا تتغير.', 1),
(b20a292f-76b3-5600-b848-62c90ff56b95, 'c780ae98-c8a7-5916-bf66-758a3269489c', 'لطلب إعادة ما قيل:', 'multiple_choice', '["¿Puedes repite?","¿Puedes repetir?","¿Puedes repetiendo?","¿Puedes a repetir?"]'::jsonb, '¿Puedes repetir?', 'بعد poder يأتي المصدر مباشرة: ¿Puedes repetir?', 1),
(8a27db5c-68f4-5355-a80e-5a9fb13df019, '9cdb0dc6-9c6d-52c7-a279-8579d70839a1', 'حرف H في الإسبانية:', 'multiple_choice', '["يُنطق هاء","يُنطق خاء","لا يُنطق (صامت)","يُنطق شيناً"]'::jsonb, 'لا يُنطق (صامت)', 'حرف h صامت دائماً: hola تُنطق «أولا».', 1) ON CONFLICT DO NOTHING;
INSERT INTO quizzes (id, lesson_id, question, type, options, correct_answer, explanation, order_num) VALUES
(7bfbb74d-d1ef-542a-8318-6ecf6b885d33, 'b60dd0e8-3f9a-5af6-a658-959b74238501', '«الحذاء» بالإسبانية:', 'multiple_choice', '["los zapatos","la camisa","el sombrero","la falda"]'::jsonb, 'los zapatos', 'los zapatos الحذاء، وla camisa القميص، وel sombrero القبعة.', 1),
(8afb8f7b-876e-510e-9d35-d0b8db86434b, '1a23dd5a-5cf4-57c5-bc91-1797be311b51', '«اليد» بالإسبانية:', 'multiple_choice', '["la mano","la pierna","la espalda","el hombro"]'::jsonb, 'la mano', 'la mano اليد (استثناء مؤنث رغم انتهائها بـ o).', 1),
(130bee1c-2637-57ca-b0ce-8d752e41ce5d, '28361121-15d8-56cc-bee2-6a4a4c81731b', '«البندورة» بالإسبانية:', 'multiple_choice', '["el tomate","la manzana","la naranja","el pan"]'::jsonb, 'el tomate', 'el tomate البندورة، وla manzana التفاحة.', 1),
(11d70b59-7914-5786-9fc0-27badc1ee10a, 'b63c6c5b-ac14-5953-ae22-fc48ad949d0f', '«العشاء» بالإسبانية:', 'multiple_choice', '["la cena","el desayuno","la comida","la merienda"]'::jsonb, 'la cena', 'la cena وجبة المساء، وel desayuno وجبة الصباح.', 1),
(a0ada647-0fbf-5dba-831b-987484437d66, 'c939f00f-6beb-5ce6-a379-44a2fe350906', 'الفعل الذي يعني «يطبخ»:', 'multiple_choice', '["cocinar","cortar","comer","beber"]'::jsonb, 'cocinar', 'cocinar يطبخ، وcortar يقطع، وcomer يأكل.', 1),
(71289732-bd61-5282-8061-120521fc7584, '54fd4c2a-d50d-57a8-9c5e-46023a59d524', 'الطريقة المهذبة للطلب تبدأ بـ:', 'multiple_choice', '["Quisiera...","Dame...","Quiero ya...","Trae..."]'::jsonb, 'Quisiera...', 'quisiera صيغة مهذبة تعني «أودّ».', 1),
(41bbf522-3588-53c9-8613-1cd2224c54dc, '9b0183e1-f19c-5ed8-adae-ab90d1db083b', '«الفاتورة» بالإسبانية:', 'multiple_choice', '["la cuenta","la propina","la carta","la mesa"]'::jsonb, 'la cuenta', 'la cuenta الفاتورة، وla propina البقشيش.', 1),
